import{j as t}from"./vendor-react-DzFdt34V.js";import{f as m,C as k,l as x,b as h,d as y,g as q,U as C}from"./LabKit-DTUlr7C_.js";import{r as E}from"./answers-B0q8VNwW.js";import{f as A,b as Z,d as _,g as v,c as L,F as j,D as P,A as T,R as S,T as I,e as w,C as B,Q as D,h as K,i as F,L as R,j as U,k as O,l as G,S as H,m as N,n as M,a as Q,o as W,q as Y,r as V,t as J,u as X,P as aa,v as l,w as ea,x as ra,y as ia}from"./figures-CYBBBvPe.js";import{P as na}from"./PairsMemoryGame-DDWCwqtQ.js";/* empty css              *//* empty css            */import"./index-CaLS8nNJ.js";import"./vendor-i18n-D_kkcOKx.js";import"./vendor-CAIZfmPq.js";import"./vendor-katex-CdCLdKXh.js";import"./answers-BOJ3EtyK.js";import"./figures-ChixD0CS.js";import"./plane-BLDILmst.js";const a=(i,c,u)=>({eu:i,es:c,ar:u.replace(/\{,\}/g,".")}),r=i=>({eu:i,es:i,ar:i.replace(/\{,\}/g,".")}),d=i=>{const[c,u=""]=i.split(",");return m(Number(c+u),10**u.length)},n=i=>m(i),oa=[{id:1301,prompt:a("Zenbat diagonal ditu pentagono batek?","¿Cuántas diagonales tiene un pentágono?","كم قطرًا للمخمس؟"),options:[r("$5$"),r("$10$"),r("$2$")],correctIndex:0,explanation:a("Erpin bakoitzetik 2; bakoitza bi aldiz zenbatzen da: $\\frac{5\\cdot 2}{2}=5$.","De cada vértice salen 2; cada una se cuenta dos veces: $\\frac{5\\cdot 2}{2}=5$.","من كل رأس قطران؛ وكل قطر يُحسب مرتين: $\\frac{5\\cdot 2}{2}=5$."),topic:"diagonals"},{id:1302,prompt:a("Zenbat egiten dute hexagono baten barne-angeluek?","¿Cuánto suman los ángulos interiores de un hexágono?","كم مجموع الزوايا الداخلية للمسدس؟"),options:[r("$540^{\\circ}$"),r("$720^{\\circ}$"),r("$1080^{\\circ}$")],correctIndex:1,explanation:a("4 triangelutan banatzen da: $(6-2)\\cdot 180^{\\circ}=720^{\\circ}$.","Se divide en 4 triángulos: $(6-2)\\cdot 180^{\\circ}=720^{\\circ}$.","ينقسم إلى 4 مثلثات: $(6-2)\\cdot 180^{\\circ}=720^{\\circ}$."),topic:"angle-sum"},{id:1303,prompt:a("Zenbat da oktogono erregularraren angelu zentrala?","¿Cuánto mide el ángulo central del octógono regular?","كم قياس الزاوية المركزية للمثمن المنتظم؟"),options:[r("$45^{\\circ}$"),r("$135^{\\circ}$"),r("$60^{\\circ}$")],correctIndex:0,explanation:a("$360^{\\circ}\\mathbin{:}8=45^{\\circ}$. $135^{\\circ}$ barne-angelua da.","$360^{\\circ}\\mathbin{:}8=45^{\\circ}$. $135^{\\circ}$ es el ángulo interior.","$360^{\\circ}\\mathbin{:}8=45^{\\circ}$. أما $135^{\\circ}$ فهي الزاوية الداخلية."),topic:"regular-angles"},{id:1304,prompt:a("Zein zuzenkirekin eraiki daiteke triangelu bat?","¿Con qué segmentos se puede construir un triángulo?","بأي قطع يمكن إنشاء مثلث؟"),options:[r("2, 3, 6 cm"),r("4, 4, 9 cm"),r("5, 6, 8 cm")],correctIndex:2,explanation:a("Alde handiena beste bien batura baino txikiagoa izan behar da: $8<5+6=11$. Besteetan $6>2+3$ eta $9>4+4$.","El lado mayor tiene que ser menor que la suma de los otros dos: $8<5+6=11$. En los otros, $6>2+3$ y $9>4+4$.","يجب أن يكون الضلع الأكبر أصغر من مجموع الآخرين: $8<5+6=11$. وفي الأخريين $6>2+3$ و$9>4+4$."),topic:"triangle-exists"},{id:1305,prompt:a("Non dago triangelu angeluzuzen baten zirkunzentroa?","¿Dónde está el circuncentro de un triángulo rectángulo?","أين يقع مركز الدائرة المحيطة بمثلث قائم؟"),options:[a("Triangeluaren barruan","Dentro del triángulo","داخل المثلث"),a("Hipotenusaren erdiko puntuan","En el punto medio de la hipotenusa","في منتصف الوتر"),a("Triangeluaren kanpoan","Fuera del triángulo","خارج المثلث")],correctIndex:1,explanation:a("Angeluzuzenean zirkunzentroa hipotenusaren erdian dago, eta erradioa hipotenusaren erdia da.","En el rectángulo el circuncentro está en la mitad de la hipotenusa, y el radio es la mitad de la hipotenusa.","في المثلث القائم يقع مركز الدائرة المحيطة في منتصف الوتر، ونصف قطرها نصف الوتر."),topic:"centers"},{id:1306,prompt:a("Paralelogramo baten diagonalak berdinak eta perpendikularrak dira. Zer da?","Las diagonales de un paralelogramo son iguales y perpendiculares. ¿Qué es?","قطرا متوازي أضلاع متساويان ومتعامدان. ما هو؟"),options:[a("Erronboa","Un rombo","معيّن"),a("Laukizuzena","Un rectángulo","مستطيل"),a("Karratua","Un cuadrado","مربع")],correctIndex:2,explanation:a("Berdinak: laukizuzena. Perpendikularrak: erronboa. Biak batera: karratua.","Iguales: rectángulo. Perpendiculares: rombo. Las dos cosas: cuadrado.","متساويان: مستطيل. متعامدان: معيّن. الأمران معًا: مربع."),topic:"quad-diagonals"},{id:1307,prompt:a("Bi zirkunferentziaren erradioak 5 cm eta 3 cm dira, eta zentroak 8 cm-ra daude. Nolakoak dira?","Dos circunferencias tienen radios de 5 cm y 3 cm, y sus centros están a 8 cm. ¿Cómo son?","نصفا قطري دائرتين 5 سم و3 سم، والبعد بين مركزيهما 8 سم. كيف هما؟"),options:[a("Ebakitzaileak","Secantes","متقاطعتان"),a("Kanpotik ukitzaileak","Tangentes exteriores","متماستان من الخارج"),a("Barnekoak","Interiores","متداخلتان")],correctIndex:1,explanation:a("$5+3=8$, zentroen arteko distantzia bera: kanpotik ukitzen dira.","$5+3=8$, justo la distancia entre los centros: se tocan por fuera.","$5+3=8$، وهو البعد بين المركزين بالضبط: تتماسان من الخارج."),topic:"two-circles"},{id:1308,prompt:a("Zein da 5 cm eta 3 cm-ko erradioak dituen koroa zirkularraren azalera? ($\\pi\\approx 3{,}14$)","¿Cuál es el área de la corona circular de radios 5 cm y 3 cm? ($\\pi\\approx 3{,}14$)","ما مساحة الحلقة الدائرية التي نصفا قطريها 5 سم و3 سم؟ ($\\pi\\approx 3{,}14$)"),options:[r("$12{,}56$ cm²"),r("$50{,}24$ cm²"),r("$25{,}12$ cm²")],correctIndex:1,explanation:a("Lehenik karratuak, gero kendu: $3{,}14\\cdot(25-9)=50{,}24$. $3{,}14\\cdot(5-3)^{2}$ okerra da.","Primero los cuadrados, luego la resta: $3{,}14\\cdot(25-9)=50{,}24$. $3{,}14\\cdot(5-3)^{2}$ es un error.","المربعات أولًا ثم الطرح: $3{,}14\\cdot(25-9)=50{,}24$. أما $3{,}14\\cdot(5-3)^{2}$ فخطأ."),topic:"sector-ring"}],ta=[{id:1,stage:"polygons",prompt:a("Zenbat diagonal ditu oktogono batek (8 alde)?","¿Cuántas diagonales tiene un octógono (8 lados)?","كم قطرًا للمثمن (8 أضلاع)؟"),expected:n(20),hint:a("Erpin bakoitzetik $8-3$; gero zati bi.","De cada vértice, $8-3$; luego entre dos.","من كل رأس $8-3$؛ ثم على اثنين."),explanation:r("$\\frac{8\\cdot 5}{2}=\\frac{40}{2}=20$")},{id:2,stage:"polygons",prompt:a("Zenbat egiten dute heptagono baten (7 alde) barne-angeluek? Idatzi gradu-kopurua.","¿Cuánto suman los ángulos interiores de un heptágono (7 lados)? Escribe los grados.","كم مجموع الزوايا الداخلية للمسبع (7 أضلاع)؟ اكتب عدد الدرجات."),expected:n(900),hint:a("$n-2$ triangelu.","$n-2$ triángulos.","$n-2$ مثلثات."),explanation:r("$(7-2)\\cdot 180^{\\circ}=5\\cdot 180^{\\circ}=900^{\\circ}$")},{id:3,stage:"polygons",prompt:a("Lauki baten hiru angeluak $80^{\\circ}$, $95^{\\circ}$ eta $110^{\\circ}$ dira. Zenbat da laugarrena?","Tres ángulos de un cuadrilátero miden $80^{\\circ}$, $95^{\\circ}$ y $110^{\\circ}$. ¿Cuánto mide el cuarto?","ثلاث زوايا في رباعي قياساتها $80^{\\circ}$ و$95^{\\circ}$ و$110^{\\circ}$. كم قياس الرابعة؟"),expected:n(75),hint:a("Laukiaren angeluek $360^{\\circ}$ egiten dute.","Los ángulos del cuadrilátero suman $360^{\\circ}$.","مجموع زوايا الرباعي $360^{\\circ}$."),explanation:r("$80^{\\circ}+95^{\\circ}+110^{\\circ}=285^{\\circ}\\ \\to\\ 360^{\\circ}-285^{\\circ}=75^{\\circ}$")},{id:4,stage:"polygons",prompt:a("Zenbat da oktogono erregular baten barne-angelua?","¿Cuánto mide el ángulo interior de un octógono regular?","كم قياس الزاوية الداخلية للمثمن المنتظم؟"),expected:n(135),hint:a("Batura zati 8.","La suma entre 8.","المجموع على 8."),explanation:r("$\\frac{(8-2)\\cdot 180^{\\circ}}{8}=\\frac{1080^{\\circ}}{8}=135^{\\circ}$")},{id:5,stage:"triangles",prompt:a("Triangelu baten bi aldeak 5 cm eta 9 cm dira. Zein da hirugarren aldeak izan dezakeen luzera osorik handiena (cm)?","Dos lados de un triángulo miden 5 cm y 9 cm. ¿Cuál es la mayor longitud entera (en cm) que puede tener el tercero?","ضلعان في مثلث طولاهما 5 سم و9 سم. ما أكبر طول صحيح (بالسم) يمكن أن يكون للضلع الثالث؟"),expected:n(13),hint:a("Beste bien batura baino txikiagoa.","Menor que la suma de los otros dos.","أصغر من مجموع الآخرين."),explanation:r("$x<5+9=14\\ \\to\\ x=13$")},{id:6,stage:"triangles",prompt:a("Triangelu isoszele baten angelu desberdina $50^{\\circ}$ da. Zenbat da oinarriko angelu bakoitza?","El ángulo desigual de un triángulo isósceles mide $50^{\\circ}$. ¿Cuánto mide cada ángulo de la base?","زاوية الرأس في مثلث متساوي الساقين $50^{\\circ}$. كم قياس كل زاوية من زاويتي القاعدة؟"),expected:n(65),hint:a("Kendu $180^{\\circ}$-ri eta zatitu bitan.","Réstalo de $180^{\\circ}$ y divide entre dos.","اطرحها من $180^{\\circ}$ واقسم على اثنين."),explanation:r("$(180^{\\circ}-50^{\\circ})\\mathbin{:}2=130^{\\circ}\\mathbin{:}2=65^{\\circ}$")},{id:7,stage:"triangles",prompt:a("Triangelu isoszele baten oinarriko angelu bakoitza $72^{\\circ}$ da. Zenbat da angelu desberdina?","Cada ángulo de la base de un triángulo isósceles mide $72^{\\circ}$. ¿Cuánto mide el ángulo desigual?","كل زاوية من زاويتي القاعدة في مثلث متساوي الساقين $72^{\\circ}$. كم قياس زاوية الرأس؟"),expected:n(36),hint:a("Oinarriko bi angeluak berdinak dira.","Los dos ángulos de la base son iguales.","زاويتا القاعدة متساويتان."),explanation:r("$180^{\\circ}-2\\cdot 72^{\\circ}=180^{\\circ}-144^{\\circ}=36^{\\circ}$")},{id:8,stage:"triangles",prompt:a("Triangelu angeluzuzen baten hipotenusa 10 cm da. Zenbat da zirkunferentzia zirkunskribatuaren erradioa?","La hipotenusa de un triángulo rectángulo mide 10 cm. ¿Cuánto mide el radio de la circunferencia circunscrita?","وتر مثلث قائم 10 سم. كم نصف قطر الدائرة المحيطة؟"),expected:n(5),hint:a("Zirkunzentroa hipotenusaren erdian dago.","El circuncentro está en la mitad de la hipotenusa.","مركز الدائرة المحيطة في منتصف الوتر."),explanation:r("$10\\mathbin{:}2=5$")},{id:9,stage:"quadrilaterals",prompt:a("Paralelogramo baten angelu bat $58^{\\circ}$ da. Zenbat da ondoko angelua?","Un ángulo de un paralelogramo mide $58^{\\circ}$. ¿Cuánto mide el ángulo consecutivo?","زاوية في متوازي أضلاع قياسها $58^{\\circ}$. كم قياس الزاوية المتتالية معها؟"),expected:n(122),hint:a("Ondoz ondokoek $180^{\\circ}$ egiten dute.","Los consecutivos suman $180^{\\circ}$.","مجموع المتتاليتين $180^{\\circ}$."),explanation:r("$180^{\\circ}-58^{\\circ}=122^{\\circ}$")},{id:10,stage:"quadrilaterals",prompt:a("Trapezio isoszele batean, oinarri handiko angelu bakoitza $70^{\\circ}$ da. Zenbat da oinarri txikiko bakoitza?","En un trapecio isósceles, cada ángulo de la base mayor mide $70^{\\circ}$. ¿Cuánto mide cada uno de la base menor?","في شبه منحرف متساوي الساقين، كل زاوية من زاويتي القاعدة الكبرى $70^{\\circ}$. كم قياس كل زاوية من زاويتي القاعدة الصغرى؟"),expected:n(110),hint:a("Alde ez-paralelo bereko bi angeluek $180^{\\circ}$.","Los dos ángulos de un mismo lado no paralelo suman $180^{\\circ}$.","مجموع زاويتي الضلع غير الموازي نفسه $180^{\\circ}$."),explanation:r("$180^{\\circ}-70^{\\circ}=110^{\\circ}$")},{id:11,stage:"quadrilaterals",prompt:a("Oktogono erregular batek 8 simetria-ardatz ditu. Zer angelu eratzen dute ondoz ondoko bik?","Un octógono regular tiene 8 ejes de simetría. ¿Qué ángulo forman dos contiguos?","للمثمن المنتظم 8 محاور تناظر. ما الزاوية بين محورين متجاورين؟"),expected:d("22,5"),hint:a("Ardatzek $180^{\\circ}$ banatzen dute.","Los ejes se reparten $180^{\\circ}$.","تتقاسم المحاور $180^{\\circ}$."),explanation:r("$180^{\\circ}\\mathbin{:}8=22{,}5^{\\circ}$")},{id:12,stage:"quadrilaterals",prompt:a("Lauki baten angeluak $x$, $x$, $2x$ eta $2x$ dira. Zenbat da $x$?","Los ángulos de un cuadrilátero miden $x$, $x$, $2x$ y $2x$. ¿Cuánto vale $x$?","زوايا رباعي قياساتها $x$ و$x$ و$2x$ و$2x$. كم قيمة $x$؟"),expected:n(60),hint:a("Guztira $6x$, eta laukiaren angeluek $360^{\\circ}$.","En total $6x$, y los ángulos del cuadrilátero suman $360^{\\circ}$.","المجموع $6x$، ومجموع زوايا الرباعي $360^{\\circ}$."),explanation:r("$6x=360^{\\circ}\\ \\to\\ x=360^{\\circ}\\mathbin{:}6=60^{\\circ}$")},{id:13,stage:"circles",prompt:a("Zuzen ukitzaile bat zirkunferentzia baten zentrotik 7 cm-ra dago. Zenbat da diametroa?","Una recta tangente a una circunferencia está a 7 cm del centro. ¿Cuánto mide el diámetro?","مستقيم مماس لدائرة يبعد عن مركزها 7 سم. كم طول القطر؟"),expected:n(14),hint:a("Ukitzailean $d=r$.","En la tangente, $d=r$.","في المماس $d=r$."),explanation:r("$r=7\\ \\to\\ 2\\cdot 7=14$")},{id:14,stage:"circles",prompt:a("5 cm eta 3 cm-ko erradioak dituzten bi zirkunferentzia kanpotik ukitzaileak dira. Zer distantziara daude zentroak?","Dos circunferencias de radios 5 cm y 3 cm son tangentes exteriores. ¿A qué distancia están sus centros?","دائرتان نصفا قطريهما 5 سم و3 سم متماستان من الخارج. كم البعد بين مركزيهما؟"),expected:n(8),hint:a("Kanpotik ukitzaileak: $d=r_1+r_2$.","Tangentes exteriores: $d=r_1+r_2$.","متماستان من الخارج: $d=r_1+r_2$."),explanation:r("$5+3=8$")},{id:15,stage:"circles",prompt:a("9 cm eta 4 cm-ko erradioak dituzten bi zirkunferentzia barrutik ukitzaileak dira. Zer distantziara daude zentroak?","Dos circunferencias de radios 9 cm y 4 cm son tangentes interiores. ¿A qué distancia están sus centros?","دائرتان نصفا قطريهما 9 سم و4 سم متماستان من الداخل. كم البعد بين مركزيهما؟"),expected:n(5),hint:a("Barrutik ukitzaileak: $d=r_1-r_2$.","Tangentes interiores: $d=r_1-r_2$.","متماستان من الداخل: $d=r_1-r_2$."),explanation:r("$9-4=5$")},{id:16,stage:"circles",prompt:a("Angelu zentral bat $140^{\\circ}$ da. Zenbat da arku bera hartzen duen angelu inskribatua?","Un ángulo central mide $140^{\\circ}$. ¿Cuánto mide un ángulo inscrito que abarca el mismo arco?","زاوية مركزية قياسها $140^{\\circ}$. كم قياس الزاوية المحيطية التي تحصر القوس نفسه؟"),expected:n(70),hint:a("Inskribatua zentralaren erdia da.","El inscrito es la mitad del central.","المحيطية نصف المركزية."),explanation:r("$140^{\\circ}\\mathbin{:}2=70^{\\circ}$")},{id:17,stage:"areas",prompt:a("12 cm × 8 cm-ko ohol batek 3 cm-ko aldeko zulo karratu bat du. Zein da oholaren azalera (cm²)?","Una tabla de 12 cm × 8 cm tiene un agujero cuadrado de 3 cm de lado. ¿Cuál es el área de la tabla (cm²)?","لوح أبعاده 12 سم × 8 سم فيه ثقب مربع طول ضلعه 3 سم. ما مساحة اللوح (سم²)؟"),expected:n(87),hint:a("Ohola osoa ken zuloa.","La tabla entera menos el agujero.","اللوح كاملًا ناقص الثقب."),explanation:r("$12\\cdot 8-3\\cdot 3=96-9=87$")},{id:18,stage:"areas",prompt:a("Kalkulatu 6 cm-ko erradioa eta $60^{\\circ}$-ko angelua dituen sektorearen azalera ($\\pi\\approx 3{,}14$).","Calcula el área de un sector de 6 cm de radio y $60^{\\circ}$ ($\\pi\\approx 3{,}14$).","احسب مساحة قطاع نصف قطره 6 سم وزاويته $60^{\\circ}$ ($\\pi\\approx 3{,}14$)."),expected:d("18,84"),hint:a("$60^{\\circ}$ zirkuluaren seirena da.","$60^{\\circ}$ es la sexta parte del círculo.","$60^{\\circ}$ سدس القرص."),explanation:r("$\\frac{3{,}14\\cdot 6^{2}\\cdot 60}{360}=\\frac{113{,}04}{6}=18{,}84$")},{id:19,stage:"areas",prompt:a("Kalkulatu 10 cm eta 6 cm-ko erradioak dituen koroa zirkularraren azalera ($\\pi\\approx 3{,}14$).","Calcula el área de la corona circular de radios 10 cm y 6 cm ($\\pi\\approx 3{,}14$).","احسب مساحة الحلقة الدائرية التي نصفا قطريها 10 سم و6 سم ($\\pi\\approx 3{,}14$)."),expected:d("200,96"),hint:a("$\\pi\\cdot(R^{2}-r^{2})$: lehenik karratuak.","$\\pi\\cdot(R^{2}-r^{2})$: primero los cuadrados.","$\\pi\\cdot(R^{2}-r^{2})$: المربعات أولًا."),explanation:r("$3{,}14\\cdot(10^{2}-6^{2})=3{,}14\\cdot 64=200{,}96$")},{id:20,stage:"areas",prompt:a("12 m × 9 m-ko lorategi bat hesiz inguratu nahi da. Metro bakoitzak 5 € balio du. Zenbat balio du hesiak?","Se quiere vallar un jardín de 12 m × 9 m. Cada metro de valla cuesta 5 €. ¿Cuánto cuesta la valla?","نريد إحاطة حديقة 12 م × 9 م بسياج. ثمن المتر 5 €. كم ثمن السياج؟"),expected:n(210),hint:a("Inguratu: perimetroa.","Rodear: perímetro.","الإحاطة: المحيط."),explanation:r("$2\\cdot 12+2\\cdot 9=42\\ \\to\\ 42\\cdot 5=210$")}],ca=[{id:101,stage:"polygons",points:10,context:"starter",prompt:a("Zenbat diagonal ditu dekagono batek (10 alde)?","¿Cuántas diagonales tiene un decágono (10 lados)?","كم قطرًا للمعشّر (10 أضلاع)؟"),expected:n(35),hint:a("$\\frac{n\\cdot(n-3)}{2}$ eta $n=10$.","$\\frac{n\\cdot(n-3)}{2}$ con $n=10$.","$\\frac{n\\cdot(n-3)}{2}$ مع $n=10$."),explanation:r("$\\frac{10\\cdot 7}{2}=\\frac{70}{2}=35$")},{id:102,stage:"polygons",points:20,context:"advanced",prompt:a("Poligono batek 14 diagonal ditu. Zenbat alde ditu?","Un polígono tiene 14 diagonales. ¿Cuántos lados tiene?","لمضلع 14 قطرًا. كم ضلعًا له؟"),expected:n(7),hint:a("Probatu: hexagonoak 9 ditu, eta hurrengoak?","Prueba: el hexágono tiene 9, ¿y el siguiente?","جرّب: للمسدس 9، فماذا عن التالي؟"),explanation:r("$\\frac{7\\cdot 4}{2}=\\frac{28}{2}=14$")},{id:103,stage:"polygons",points:30,context:"advanced",prompt:a("Poligono baten barne-angeluek $1440^{\\circ}$ egiten dute. Zenbat alde ditu?","Los ángulos interiores de un polígono suman $1440^{\\circ}$. ¿Cuántos lados tiene?","مجموع الزوايا الداخلية لمضلع $1440^{\\circ}$. كم ضلعًا له؟"),expected:n(10),hint:a("Zenbat triangelu dira? Gehitu 2.","¿Cuántos triángulos son? Suma 2.","كم مثلثًا؟ أضف 2."),explanation:r("$1440^{\\circ}\\mathbin{:}180^{\\circ}=8\\ \\to\\ n=8+2=10$")},{id:104,stage:"triangles",points:10,context:"starter",prompt:a("Triangelu isoszele baten angelu desberdina zuzena da ($90^{\\circ}$). Zenbat da oinarriko bakoitza?","El ángulo desigual de un triángulo isósceles es recto ($90^{\\circ}$). ¿Cuánto mide cada ángulo de la base?","زاوية الرأس في مثلث متساوي الساقين قائمة ($90^{\\circ}$). كم قياس كل زاوية من زاويتي القاعدة؟"),expected:n(45),hint:a("$(180^{\\circ}-90^{\\circ})\\mathbin{:}2$.","$(180^{\\circ}-90^{\\circ})\\mathbin{:}2$.","$(180^{\\circ}-90^{\\circ})\\mathbin{:}2$."),explanation:r("$(180^{\\circ}-90^{\\circ})\\mathbin{:}2=90^{\\circ}\\mathbin{:}2=45^{\\circ}$")},{id:105,stage:"triangles",points:20,context:"advanced",prompt:a("Triangelu baten bi aldeak 4 cm eta 10 cm dira. Zein da hirugarrenaren luzera osorik txikiena (cm)?","Dos lados de un triángulo miden 4 cm y 10 cm. ¿Cuál es la menor longitud entera (en cm) del tercero?","ضلعان في مثلث طولاهما 4 سم و10 سم. ما أصغر طول صحيح (بالسم) للضلع الثالث؟"),expected:n(7),hint:a("10 cm-koa alde handiena bada, beste biek 10 baino gehiago batu behar dute.","Si el de 10 cm es el mayor, los otros dos tienen que sumar más de 10.","إذا كان ضلع 10 سم هو الأكبر فيجب أن يزيد مجموع الآخرين على 10."),explanation:r("$x>10-4=6\\ \\to\\ x=7$")},{id:106,stage:"triangles",points:30,context:"advanced",prompt:a("Triangelu angeluzuzen baten katetoak 6 cm eta 8 cm dira. Zenbat da zirkunferentzia zirkunskribatuaren erradioa?","Los catetos de un triángulo rectángulo miden 6 cm y 8 cm. ¿Cuánto mide el radio de la circunferencia circunscrita?","الضلعان القائمان في مثلث قائم 6 سم و8 سم. كم نصف قطر الدائرة المحيطة؟"),expected:n(5),hint:a("Pitagorasekin hipotenusa; erradioa haren erdia.","Con Pitágoras, la hipotenusa; el radio es la mitad.","بفيثاغورس الوتر؛ ونصف القطر نصفه."),explanation:r("$\\sqrt{6^{2}+8^{2}}=\\sqrt{100}=10\\ \\to\\ 10\\mathbin{:}2=5$")},{id:107,stage:"quadrilaterals",points:10,context:"starter",prompt:a("Erronbo baten angelu bat $75^{\\circ}$ da. Zenbat da ondoko angelua?","Un ángulo de un rombo mide $75^{\\circ}$. ¿Cuánto mide el consecutivo?","زاوية في معيّن قياسها $75^{\\circ}$. كم قياس المتتالية معها؟"),expected:n(105),hint:a("Erronboa paralelogramoa da.","El rombo es un paralelogramo.","المعيّن متوازي أضلاع."),explanation:r("$180^{\\circ}-75^{\\circ}=105^{\\circ}$")},{id:108,stage:"quadrilaterals",points:20,context:"advanced",prompt:a("Zer angelu eratzen dute dodekagono erregular baten (12 alde) ondoz ondoko bi simetria-ardatzek?","¿Qué ángulo forman dos ejes de simetría contiguos de un dodecágono regular (12 lados)?","ما الزاوية بين محوري تناظر متجاورين في المضلع المنتظم ذي 12 ضلعًا؟"),expected:n(15),hint:a("12 ardatz, $180^{\\circ}$ banatzen.","12 ejes repartiendo $180^{\\circ}$.","12 محورًا تتقاسم $180^{\\circ}$."),explanation:r("$180^{\\circ}\\mathbin{:}12=15^{\\circ}$")},{id:109,stage:"quadrilaterals",points:30,context:"advanced",prompt:a("Trapezio isoszele batean, oinarri txikiko angelua oinarri handikoaren bikoitza da. Zenbat da oinarri handiko angelua?","En un trapecio isósceles, el ángulo de la base menor es el doble que el de la base mayor. ¿Cuánto mide el de la base mayor?","في شبه منحرف متساوي الساقين، زاوية القاعدة الصغرى ضعف زاوية القاعدة الكبرى. كم قياس زاوية القاعدة الكبرى؟"),expected:n(60),hint:a("Alde ez-paralelo bereko bi angeluek $180^{\\circ}$: $x+2x$.","Los dos ángulos de un lado no paralelo suman $180^{\\circ}$: $x+2x$.","مجموع زاويتي الضلع غير الموازي $180^{\\circ}$: $x+2x$."),explanation:r("$x+2x=3x=180^{\\circ}\\ \\to\\ x=180^{\\circ}\\mathbin{:}3=60^{\\circ}$")},{id:110,stage:"circles",points:10,context:"starter",prompt:a("8 cm eta 5 cm-ko erradioak dituzten bi zirkunferentzia kanpotik ukitzaileak dira. Zer distantziara daude zentroak?","Dos circunferencias de radios 8 cm y 5 cm son tangentes exteriores. ¿A qué distancia están sus centros?","دائرتان نصفا قطريهما 8 سم و5 سم متماستان من الخارج. كم البعد بين مركزيهما؟"),expected:n(13),hint:a("$d=r_1+r_2$.","$d=r_1+r_2$.","$d=r_1+r_2$."),explanation:r("$8+5=13$")},{id:111,stage:"circles",points:30,context:"advanced",prompt:a("Zirkunferentzia batean inskribatutako triangelu baten alde bat diametroa da. Beste angelu bat $35^{\\circ}$ da. Zenbat da hirugarrena?","Un triángulo inscrito en una circunferencia tiene un lado que es un diámetro. Otro ángulo mide $35^{\\circ}$. ¿Cuánto mide el tercero?","مثلث محاط بدائرة أحد أضلاعه قطر. وزاوية أخرى فيه $35^{\\circ}$. كم قياس الثالثة؟"),expected:n(55),hint:a("Diametroaren gaineko angelu inskribatua zuzena da.","El ángulo inscrito que abarca el diámetro es recto.","الزاوية المحيطية التي تحصر القطر قائمة."),explanation:r("$180^{\\circ}-90^{\\circ}-35^{\\circ}=55^{\\circ}$")},{id:112,stage:"circles",points:20,context:"advanced",prompt:a("Zuzen bat 15 cm-ko erradioko zirkunferentzia baten zentrotik 9 cm-ra pasatzen da. Zenbat da sortzen duen korda?","Una recta pasa a 9 cm del centro de una circunferencia de 15 cm de radio. ¿Cuánto mide la cuerda que determina?","يمر مستقيم على بعد 9 سم من مركز دائرة نصف قطرها 15 سم. كم طول الوتر الذي يحدده؟"),expected:n(24),hint:a("Erradioa, distantzia eta kordaren erdia: triangelu angeluzuzena.","Radio, distancia y media cuerda: un triángulo rectángulo.","نصف القطر والبعد ونصف الوتر: مثلث قائم."),explanation:r("$\\sqrt{15^{2}-9^{2}}=\\sqrt{144}=12\\ \\to\\ 2\\cdot 12=24$")},{id:113,stage:"areas",points:20,context:"advanced",prompt:a("Kalkulatu 9 cm-ko erradioko zirkunferentzia baten $120^{\\circ}$-ko arkuaren luzera ($\\pi\\approx 3{,}14$).","Calcula la longitud de un arco de $120^{\\circ}$ en una circunferencia de 9 cm de radio ($\\pi\\approx 3{,}14$).","احسب طول قوس $120^{\\circ}$ في دائرة نصف قطرها 9 سم ($\\pi\\approx 3{,}14$)."),expected:d("18,84"),hint:a("$120^{\\circ}$ zirkunferentziaren herena da.","$120^{\\circ}$ es un tercio de la circunferencia.","$120^{\\circ}$ ثلث الدائرة."),explanation:r("$\\frac{2\\cdot 3{,}14\\cdot 9\\cdot 120}{360}=\\frac{56{,}52}{3}=18{,}84$")},{id:114,stage:"areas",points:30,context:"advanced",prompt:a("10 cm-ko aldeko karratu batean zirkulu bat inskribatu da. Zein da karratuaren eta zirkuluaren arteko azalera (lau izkinak)? ($\\pi\\approx 3{,}14$)","En un cuadrado de 10 cm de lado se inscribe un círculo. ¿Cuál es el área entre el cuadrado y el círculo (las cuatro esquinas)? ($\\pi\\approx 3{,}14$)","رُسم قرص داخل مربع طول ضلعه 10 سم. ما المساحة بين المربع والقرص (الأركان الأربعة)؟ ($\\pi\\approx 3{,}14$)"),expected:d("21,5"),hint:a("Zirkuluaren erradioa aldearen erdia da.","El radio del círculo es la mitad del lado.","نصف قطر القرص نصف الضلع."),explanation:r("$10^{2}-3{,}14\\cdot 5^{2}=100-78{,}5=21{,}5$")}],ua=[{id:"polygons",title:a("Poligonoak: diagonalak eta angeluak","Polígonos: diagonales y ángulos","المضلعات: الأقطار والزوايا"),items:[{id:1,difficulty:"easy",question:a("Zenbat diagonal ateratzen dira heptagono baten erpin batetik?","¿Cuántas diagonales salen de un vértice de un heptágono?","كم قطرًا يخرج من رأس واحد في المسبع؟"),solution:r("$7-3=4$"),answer:{expected:n(4)}},{id:2,difficulty:"easy",question:a("Zenbat diagonal ditu heptagono batek guztira?","¿Cuántas diagonales tiene un heptágono en total?","كم قطرًا للمسبع في المجموع؟"),solution:r("$\\frac{7\\cdot 4}{2}=\\frac{28}{2}=14$"),answer:{expected:n(14)}},{id:3,difficulty:"easy",question:a("Zenbat egiten dute pentagono baten barne-angeluek?","¿Cuánto suman los ángulos interiores de un pentágono?","كم مجموع الزوايا الداخلية للمخمس؟"),solution:r("$(5-2)\\cdot 180^{\\circ}=540^{\\circ}$"),answer:{expected:n(540)}},{id:4,difficulty:"medium",question:a("Osatu taula: 3, 4, 5, 6, 7 eta 8 aldeko poligonoen diagonal kopurua.","Completa la tabla: número de diagonales de los polígonos de 3, 4, 5, 6, 7 y 8 lados.","أكمل الجدول: عدد أقطار المضلعات ذات 3 و4 و5 و6 و7 و8 أضلاع."),solution:a("0, 2, 5, 9, 14 eta 20. Aldea gehitzean, diagonal gehiago gehitzen dira: +2, +3, +4, +5, +6.","0, 2, 5, 9, 14 y 20. Al añadir un lado, se añaden cada vez más: +2, +3, +4, +5, +6.","0 و2 و5 و9 و14 و20. وكلما أُضيف ضلع زادت الأقطار أكثر: +2، +3، +4، +5، +6.")},{id:5,difficulty:"medium",question:a("Zenbat da dekagono erregular baten barne-angelua?","¿Cuánto mide el ángulo interior de un decágono regular?","كم قياس الزاوية الداخلية للمعشّر المنتظم؟"),solution:r("$\\frac{(10-2)\\cdot 180^{\\circ}}{10}=\\frac{1440^{\\circ}}{10}=144^{\\circ}$"),answer:{expected:n(144)}},{id:6,difficulty:"medium",question:a("Zenbat da pentagono erregular baten angelu zentrala?","¿Cuánto mide el ángulo central de un pentágono regular?","كم قياس الزاوية المركزية للمخمس المنتظم؟"),solution:r("$360^{\\circ}\\mathbin{:}5=72^{\\circ}$"),answer:{expected:n(72)}},{id:7,difficulty:"medium",question:a("Hexagono baten bost angelu $100^{\\circ}$, $120^{\\circ}$, $130^{\\circ}$, $140^{\\circ}$ eta $110^{\\circ}$ dira. Zenbat da seigarrena?","Cinco ángulos de un hexágono miden $100^{\\circ}$, $120^{\\circ}$, $130^{\\circ}$, $140^{\\circ}$ y $110^{\\circ}$. ¿Cuánto mide el sexto?","خمس زوايا في مسدس قياساتها $100^{\\circ}$ و$120^{\\circ}$ و$130^{\\circ}$ و$140^{\\circ}$ و$110^{\\circ}$. كم قياس السادسة؟"),solution:r("$720^{\\circ}-(100^{\\circ}+120^{\\circ}+130^{\\circ}+140^{\\circ}+110^{\\circ})=720^{\\circ}-600^{\\circ}=120^{\\circ}$"),answer:{expected:n(120)}},{id:8,difficulty:"hard",question:a("Oktogono erregularrek bakarrik ezin dute zorua lauzatu. Zergatik? Eta oktogonoak eta karratuak nahastuta?","Los octógonos regulares solos no pueden embaldosar el suelo. ¿Por qué? ¿Y mezclando octógonos y cuadrados?","لا تستطيع المثمنات المنتظمة وحدها تبليط الأرض. لماذا؟ وماذا لو خلطنا مثمنات ومربعات؟"),solution:a("$135^{\\circ}$-k ez du $360^{\\circ}$ zatitzen. Bi oktogono eta karratu bat bai: $135^{\\circ}+135^{\\circ}+90^{\\circ}=360^{\\circ}$.","$135^{\\circ}$ no divide a $360^{\\circ}$. Dos octógonos y un cuadrado, sí: $135^{\\circ}+135^{\\circ}+90^{\\circ}=360^{\\circ}$.","$135^{\\circ}$ لا تقسم $360^{\\circ}$. أما مثمنان ومربع فنعم: $135^{\\circ}+135^{\\circ}+90^{\\circ}=360^{\\circ}$.")},{id:9,difficulty:"hard",question:a("Zein poligono erregularrek du $40^{\\circ}$-ko angelu zentrala? Idatzi alde kopurua.","¿Qué polígono regular tiene un ángulo central de $40^{\\circ}$? Escribe el número de lados.","أي مضلع منتظم زاويته المركزية $40^{\\circ}$؟ اكتب عدد الأضلاع."),solution:a("$360^{\\circ}\\mathbin{:}40^{\\circ}=9$: eneagonoa.","$360^{\\circ}\\mathbin{:}40^{\\circ}=9$: el eneágono.","$360^{\\circ}\\mathbin{:}40^{\\circ}=9$: المتسع."),answer:{expected:n(9)}},{id:10,difficulty:"hard",question:a("Poligono baten barne-angeluek $1260^{\\circ}$ egiten dute. Zenbat alde ditu?","Los ángulos interiores de un polígono suman $1260^{\\circ}$. ¿Cuántos lados tiene?","مجموع الزوايا الداخلية لمضلع $1260^{\\circ}$. كم ضلعًا له؟"),solution:r("$1260^{\\circ}\\mathbin{:}180^{\\circ}=7\\ \\to\\ n=7+2=9$"),answer:{expected:n(9)}}]},{id:"triangles",title:a("Triangeluak","Triángulos","المثلثات"),items:[{id:11,difficulty:"easy",question:a("Triangelu bat eraiki daiteke 5, 6 eta 12 cm-ko zuzenkiekin?","¿Se puede construir un triángulo con segmentos de 5, 6 y 12 cm?","هل يمكن إنشاء مثلث بقطع أطوالها 5 و6 و12 سم؟"),solution:a("Ez: $5+6=11$, eta 12 handiagoa da.","No: $5+6=11$, y 12 es mayor.","لا: $5+6=11$، و12 أكبر.")},{id:12,difficulty:"easy",question:a("Eta 6, 6 eta 3 cm-koekin?","¿Y con 6, 6 y 3 cm?","وبقطع 6 و6 و3 سم؟"),solution:a("Bai: $6<6+3=9$. Isoszelea da.","Sí: $6<6+3=9$. Es isósceles.","نعم: $6<6+3=9$. إنه متساوي الساقين.")},{id:13,difficulty:"easy",question:a("Zenbat da triangelu aldeberdin baten angelu bakoitza, 2 cm-koa edo 2 km-koa izan?","¿Cuánto mide cada ángulo de un triángulo equilátero, sea de 2 cm o de 2 km?","كم قياس كل زاوية في مثلث متساوي الأضلاع، سواء كان ضلعه 2 سم أو 2 كم؟"),solution:r("$180^{\\circ}\\mathbin{:}3=60^{\\circ}$"),answer:{expected:n(60)}},{id:14,difficulty:"medium",question:a("Triangelu isoszele baten angelu desberdina $30^{\\circ}$ da. Zenbat da oinarriko bakoitza?","El ángulo desigual de un triángulo isósceles mide $30^{\\circ}$. ¿Cuánto mide cada ángulo de la base?","زاوية الرأس في مثلث متساوي الساقين $30^{\\circ}$. كم قياس كل زاوية من زاويتي القاعدة؟"),solution:r("$(180^{\\circ}-30^{\\circ})\\mathbin{:}2=150^{\\circ}\\mathbin{:}2=75^{\\circ}$"),answer:{expected:n(75)}},{id:15,difficulty:"medium",question:a("Triangelu baten aldeak $a=7$, $b=5$ eta $c=8$ cm dira. Ordenatu haien angeluak txikienetik handienera.","Los lados de un triángulo miden $a=7$, $b=5$ y $c=8$ cm. Ordena sus ángulos de menor a mayor.","أضلاع مثلث $a=7$ و$b=5$ و$c=8$ سم. رتّب زواياه من الأصغر إلى الأكبر."),solution:r("$b<a<c\\ \\to\\ \\hat{B}<\\hat{A}<\\hat{C}$")},{id:16,difficulty:"medium",question:a("Triangelu baten bi angeluak $95^{\\circ}$ eta $88^{\\circ}$ izan daitezke?","¿Pueden medir $95^{\\circ}$ y $88^{\\circ}$ dos ángulos de un triángulo?","هل يمكن أن تكون زاويتان في مثلث $95^{\\circ}$ و$88^{\\circ}$؟"),solution:a("Ez: $95^{\\circ}+88^{\\circ}=183^{\\circ}$, $180^{\\circ}$ baino gehiago.","No: $95^{\\circ}+88^{\\circ}=183^{\\circ}$, más de $180^{\\circ}$.","لا: $95^{\\circ}+88^{\\circ}=183^{\\circ}$، أكثر من $180^{\\circ}$.")},{id:17,difficulty:"medium",question:a("Non dago triangelu angeluzuzen baten ortozentroa? Eta angelu-kamutsarena?","¿Dónde está el ortocentro de un triángulo rectángulo? ¿Y el de un obtusángulo?","أين يقع ملتقى ارتفاعات مثلث قائم؟ ومثلث منفرج؟"),solution:a("Angeluzuzenean, angelu zuzeneko erpinean. Angelu-kamutsean, triangeluaren kanpoan.","En el rectángulo, en el vértice del ángulo recto. En el obtusángulo, fuera del triángulo.","في القائم عند رأس الزاوية القائمة. وفي المنفرج خارج المثلث.")},{id:18,difficulty:"hard",question:a("Triangelu isoszele baten oinarriko angelu bat $40^{\\circ}$ da. Angelu-zorrotza, angeluzuzena ala angelu-kamutsa da?","Un ángulo de la base de un triángulo isósceles mide $40^{\\circ}$. ¿Es acutángulo, rectángulo u obtusángulo?","زاوية القاعدة في مثلث متساوي الساقين $40^{\\circ}$. أهو حاد أم قائم أم منفرج؟"),solution:a("Angelu desberdina: $180^{\\circ}-2\\cdot 40^{\\circ}=100^{\\circ}$. Angelu-kamutsa da.","El ángulo desigual: $180^{\\circ}-2\\cdot 40^{\\circ}=100^{\\circ}$. Es obtusángulo.","زاوية الرأس: $180^{\\circ}-2\\cdot 40^{\\circ}=100^{\\circ}$. إنه منفرج الزاوية.")},{id:19,difficulty:"hard",question:a("Triangelu angeluzuzen baten katetoak 5 cm eta 12 cm dira. Zenbat da zirkunferentzia zirkunskribatuaren erradioa?","Los catetos de un triángulo rectángulo miden 5 cm y 12 cm. ¿Cuánto mide el radio de la circunferencia circunscrita?","الضلعان القائمان في مثلث قائم 5 سم و12 سم. كم نصف قطر الدائرة المحيطة؟"),solution:r("$\\sqrt{5^{2}+12^{2}}=\\sqrt{169}=13\\ \\to\\ 13\\mathbin{:}2=6{,}5$"),answer:{expected:d("6,5")}},{id:20,difficulty:"hard",question:a("Triangelu baten bi aldeak 3 cm eta 8 cm dira. Zein balio oso izan ditzake hirugarrenak?","Dos lados de un triángulo miden 3 cm y 8 cm. ¿Qué valores enteros puede tomar el tercero?","ضلعان في مثلث 3 سم و8 سم. ما القيم الصحيحة الممكنة للضلع الثالث؟"),solution:a("$8-3<x<8+3$: 6, 7, 8, 9 edo 10 cm.","$8-3<x<8+3$: 6, 7, 8, 9 o 10 cm.","$8-3<x<8+3$: 6 أو 7 أو 8 أو 9 أو 10 سم.")}]},{id:"quadrilaterals",title:a("Laukiak eta simetria","Cuadriláteros y simetría","الرباعيات والتناظر"),items:[{id:21,difficulty:"easy",question:a("Paralelogramo baten angelu bat $80^{\\circ}$ da. Zenbat dira besteak?","Un ángulo de un paralelogramo mide $80^{\\circ}$. ¿Cuánto miden los otros?","زاوية في متوازي أضلاع $80^{\\circ}$. كم قياس الأخريات؟"),solution:a("Aurkakoa $80^{\\circ}$, eta ondokoak $180^{\\circ}-80^{\\circ}=100^{\\circ}$.","El opuesto, $80^{\\circ}$, y los consecutivos, $180^{\\circ}-80^{\\circ}=100^{\\circ}$.","المقابلة $80^{\\circ}$، والمتتاليتان $180^{\\circ}-80^{\\circ}=100^{\\circ}$.")},{id:22,difficulty:"easy",question:a("Zenbat simetria-ardatz ditu: a) laukizuzenak; b) erronboak; c) karratuak; d) erronboideak?","¿Cuántos ejes de simetría tiene: a) el rectángulo; b) el rombo; c) el cuadrado; d) el romboide?","كم محور تناظر لـ: أ) المستطيل؛ ب) المعيّن؛ ج) المربع؛ د) متوازي الأضلاع العادي؟"),solution:a("a) 2; b) 2; c) 4; d) bat ere ez.","a) 2; b) 2; c) 4; d) ninguno.","أ) 2؛ ب) 2؛ ج) 4؛ د) لا شيء.")},{id:23,difficulty:"easy",question:a("Zein laukik ditu diagonal perpendikularrak paralelogramoa izan gabe?","¿Qué cuadrilátero tiene las diagonales perpendiculares sin ser paralelogramo?","أي رباعي قطراه متعامدان دون أن يكون متوازي أضلاع؟"),solution:a("Kometak (trapezoide bat).","La cometa (un trapezoide).","الطائرة الورقية (رباعي عام).")},{id:24,difficulty:"medium",question:a("Lauki baten hiru angeluak $90^{\\circ}$, $90^{\\circ}$ eta $60^{\\circ}$ dira. Zenbat da laugarrena?","Tres ángulos de un cuadrilátero miden $90^{\\circ}$, $90^{\\circ}$ y $60^{\\circ}$. ¿Cuánto mide el cuarto?","ثلاث زوايا في رباعي $90^{\\circ}$ و$90^{\\circ}$ و$60^{\\circ}$. كم قياس الرابعة؟"),solution:r("$360^{\\circ}-(90^{\\circ}+90^{\\circ}+60^{\\circ})=360^{\\circ}-240^{\\circ}=120^{\\circ}$"),answer:{expected:n(120)}},{id:25,difficulty:"medium",question:a("Trapezio angeluzuzen baten angelu kamutsa $125^{\\circ}$ da. Zenbat da zorrotza?","El ángulo obtuso de un trapecio rectángulo mide $125^{\\circ}$. ¿Cuánto mide el agudo?","الزاوية المنفرجة في شبه منحرف قائم $125^{\\circ}$. كم قياس الحادة؟"),solution:r("$180^{\\circ}-125^{\\circ}=55^{\\circ}$"),answer:{expected:n(55)}},{id:26,difficulty:"medium",question:a("Bi zuzenki berdin erdian gurutzatu dira, perpendikularrak izan gabe. Muturrak lotuz gero, zer lauki sortzen da? Eta perpendikularrak balira?","Dos segmentos iguales se cortan en su punto medio sin ser perpendiculares. Al unir sus extremos, ¿qué cuadrilátero sale? ¿Y si fueran perpendiculares?","قطعتان متساويتان تتقاطعان في منتصفيهما دون تعامد. إذا وصلنا أطرافهما فأي رباعي ينتج؟ وإذا كانتا متعامدتين؟"),solution:a("Laukizuzena (diagonal berdinak). Perpendikularrak badira, karratua.","Un rectángulo (diagonales iguales). Si son perpendiculares, un cuadrado.","مستطيل (قطران متساويان). وإذا كانتا متعامدتين، مربع.")},{id:27,difficulty:"medium",question:a("Zer angelu eratzen dute hexagono erregular baten ondoz ondoko bi simetria-ardatzek?","¿Qué ángulo forman dos ejes de simetría contiguos de un hexágono regular?","ما الزاوية بين محوري تناظر متجاورين في المسدس المنتظم؟"),solution:r("$180^{\\circ}\\mathbin{:}6=30^{\\circ}$"),answer:{expected:n(30)}},{id:28,difficulty:"hard",question:a("Erronboide baten angelu bat ondokoa baino $30^{\\circ}$ handiagoa da. Zenbat da txikiena?","Un ángulo de un romboide mide $30^{\\circ}$ más que su consecutivo. ¿Cuánto mide el menor?","زاوية في متوازي أضلاع أكبر من المتتالية معها بـ$30^{\\circ}$. كم قياس الصغرى؟"),solution:r("$x+x+30^{\\circ}=180^{\\circ}\\ \\to\\ 2x=150^{\\circ}\\ \\to\\ x=75^{\\circ}$"),answer:{expected:n(75)}},{id:29,difficulty:"hard",question:a("Egia ala gezurra? a) Karratu oro erronboa da. b) Erronbo oro karratua da. c) Laukizuzen oro paralelogramoa da.","¿Verdadero o falso? a) Todo cuadrado es un rombo. b) Todo rombo es un cuadrado. c) Todo rectángulo es un paralelogramo.","صواب أم خطأ؟ أ) كل مربع معيّن. ب) كل معيّن مربع. ج) كل مستطيل متوازي أضلاع."),solution:a("a) Egia: lau alde berdin ditu. b) Gezurra: erronboaren angeluak ez dira zertan zuzenak izan. c) Egia.","a) Verdadero: tiene cuatro lados iguales. b) Falso: los ángulos del rombo no tienen por qué ser rectos. c) Verdadero.","أ) صواب: له أربعة أضلاع متساوية. ب) خطأ: زوايا المعيّن ليست قائمة بالضرورة. ج) صواب.")},{id:30,difficulty:"hard",question:a("Zenbat simetria-ardatz dituzte H, A, F eta O letrek?","¿Cuántos ejes de simetría tienen las letras H, A, F y O?","كم محور تناظر للحروف H وA وF وO؟"),solution:a("H: 2; A: 1; F: bat ere ez; O (zirkulua bada): infinitu.","H: 2; A: 1; F: ninguno; O (si es un círculo): infinitos.","H: 2؛ A: 1؛ F: لا شيء؛ O (إذا كانت دائرة): عدد لا نهائي.")}]},{id:"circles",title:a("Zirkunferentzia eta posizioak","Circunferencia y posiciones","الدائرة والأوضاع"),items:[{id:31,difficulty:"easy",question:a("Zirkunferentzia baten erradioa 4 cm da, eta zuzen bat zentrotik 4 cm-ra dago. Nolakoa da zuzena?","Una circunferencia tiene 4 cm de radio y una recta está a 4 cm del centro. ¿Cómo es la recta?","نصف قطر دائرة 4 سم ومستقيم يبعد عن المركز 4 سم. كيف المستقيم؟"),solution:a("Ukitzailea: $d=r$.","Tangente: $d=r$.","مماس: $d=r$.")},{id:32,difficulty:"easy",question:a("6 cm-ko erradioa, eta zuzena zentrotik 2 cm-ra. Nolakoa da?","Radio de 6 cm y la recta a 2 cm del centro. ¿Cómo es?","نصف القطر 6 سم والمستقيم على بعد 2 سم من المركز. كيف هو؟"),solution:a("Ebakitzailea: $2<6$.","Secante: $2<6$.","قاطع: $2<6$.")},{id:33,difficulty:"easy",question:a("Angelu inskribatu bat $25^{\\circ}$ da. Zenbat da arku bera hartzen duen zentrala?","Un ángulo inscrito mide $25^{\\circ}$. ¿Cuánto mide el central que abarca el mismo arco?","زاوية محيطية $25^{\\circ}$. كم قياس المركزية التي تحصر القوس نفسه؟"),solution:r("$2\\cdot 25^{\\circ}=50^{\\circ}$"),answer:{expected:n(50)}},{id:34,difficulty:"medium",question:a("Bi zirkunferentziaren erradioak 7 cm eta 10 cm dira. Nolakoak dira zentroak a) 9 cm-ra; b) 20 cm-ra; c) 3 cm-ra; d) 17 cm-ra; e) 0 cm-ra badaude?","Dos circunferencias tienen radios de 7 cm y 10 cm. ¿Cómo son si sus centros están a a) 9 cm; b) 20 cm; c) 3 cm; d) 17 cm; e) 0 cm?","نصفا قطري دائرتين 7 سم و10 سم. كيف هما إذا كان البعد بين المركزين أ) 9 سم؛ ب) 20 سم؛ ج) 3 سم؛ د) 17 سم؛ هـ) 0 سم؟"),solution:a("a) Ebakitzaileak; b) kanpokoak; c) barrutik ukitzaileak; d) kanpotik ukitzaileak; e) zentrokideak.","a) Secantes; b) exteriores; c) tangentes interiores; d) tangentes exteriores; e) concéntricas.","أ) متقاطعتان؛ ب) متباعدتان؛ ج) متماستان من الداخل؛ د) متماستان من الخارج؛ هـ) متحدتا المركز.")},{id:35,difficulty:"medium",question:a("6 cm eta 2,5 cm-ko erradioak dituzten bi zirkunferentzia kanpotik ukitzaileak dira. Zer distantziara daude zentroak?","Dos circunferencias de radios 6 cm y 2,5 cm son tangentes exteriores. ¿A qué distancia están los centros?","دائرتان نصفا قطريهما 6 سم و2.5 سم متماستان من الخارج. كم البعد بين المركزين؟"),solution:r("$6+2{,}5=8{,}5$"),answer:{expected:d("8,5")}},{id:36,difficulty:"medium",question:a("12 cm eta 7 cm-ko erradioak dituzten bi zirkunferentzia barrutik ukitzaileak dira. Zer distantziara daude zentroak?","Dos circunferencias de radios 12 cm y 7 cm son tangentes interiores. ¿A qué distancia están los centros?","دائرتان نصفا قطريهما 12 سم و7 سم متماستان من الداخل. كم البعد بين المركزين؟"),solution:r("$12-7=5$"),answer:{expected:n(5)}},{id:37,difficulty:"medium",question:a("Arku batek zirkunferentziaren laurdena hartzen du. Zenbat da arku hori hartzen duen angelu inskribatua?","Un arco es la cuarta parte de la circunferencia. ¿Cuánto mide un ángulo inscrito que abarca ese arco?","قوس هو ربع الدائرة. كم قياس الزاوية المحيطية التي تحصره؟"),solution:r("$360^{\\circ}\\mathbin{:}4=90^{\\circ}\\ \\to\\ 90^{\\circ}\\mathbin{:}2=45^{\\circ}$"),answer:{expected:n(45)}},{id:38,difficulty:"hard",question:a("17 cm-ko erradioko zirkunferentzia batek zuzen bat ebakitzen du, eta korda 16 cm da. Zer distantziara dago zentroa zuzenetik?","Una circunferencia de 17 cm de radio corta a una recta, y la cuerda mide 16 cm. ¿A qué distancia está el centro de la recta?","دائرة نصف قطرها 17 سم تقطع مستقيمًا، وطول الوتر 16 سم. كم يبعد المركز عن المستقيم؟"),solution:r("$\\sqrt{17^{2}-8^{2}}=\\sqrt{225}=15$"),answer:{expected:n(15)}},{id:39,difficulty:"hard",question:a("$r_1=8$ m eta $r_2=5$ m. Nolakoak dira zentroak a) 6 m-ra; b) 13 m-ra; c) 15 m-ra; d) 3 m-ra badaude?","$r_1=8$ m y $r_2=5$ m. ¿Cómo son si los centros están a a) 6 m; b) 13 m; c) 15 m; d) 3 m?","$r_1=8$ م و$r_2=5$ م. كيف هما إذا كان البعد بين المركزين أ) 6 م؛ ب) 13 م؛ ج) 15 م؛ د) 3 م؟"),solution:a("a) Ebakitzaileak; b) kanpotik ukitzaileak; c) kanpokoak; d) barrutik ukitzaileak.","a) Secantes; b) tangentes exteriores; c) exteriores; d) tangentes interiores.","أ) متقاطعتان؛ ب) متماستان من الخارج؛ ج) متباعدتان؛ د) متماستان من الداخل.")},{id:40,difficulty:"hard",question:a("Izendatu: a) bi erradio eta arku batek mugatutako zatia; b) korda batek eta arku batek mugatutakoa; c) zentro bereko bi zirkunferentziaren artekoa; d) koroa baten zati bat, bi erradiok mugatuta.","Nombra: a) la parte limitada por dos radios y un arco; b) la limitada por una cuerda y un arco; c) la que queda entre dos circunferencias con el mismo centro; d) un trozo de corona limitado por dos radios.","سمِّ: أ) الجزء المحدود بنصفي قطرين وقوس؛ ب) المحدود بوتر وقوس؛ ج) ما بين دائرتين لهما المركز نفسه؛ د) جزء من حلقة يحدّه نصفا قطرين."),solution:a("a) Sektore zirkularra; b) segmentu zirkularra; c) koroa zirkularra; d) trapezio zirkularra.","a) Sector circular; b) segmento circular; c) corona circular; d) trapecio circular.","أ) قطاع دائري؛ ب) قطعة دائرية؛ ج) حلقة دائرية؛ د) شبه منحرف دائري.")}]},{id:"areas",title:a("Irudi konposatuen azalera","Áreas de figuras compuestas","مساحات الأشكال المركّبة"),items:[{id:41,difficulty:"easy",question:a("L forma bat 8 × 3 cm-ko laukizuzen batek eta 4 × 2 cm-ko beste batek osatzen dute. Zein da azalera (cm²)?","Una L está formada por un rectángulo de 8 × 3 cm y otro de 4 × 2 cm. ¿Cuál es su área (cm²)?","شكل L مكوّن من مستطيل 8 × 3 سم وآخر 4 × 2 سم. ما مساحته (سم²)؟"),solution:r("$8\\cdot 3+4\\cdot 2=24+8=32$"),answer:{expected:n(32)}},{id:42,difficulty:"easy",question:a("Kalkulatu 10 cm-ko erradioko zirkulu-erdi baten azalera ($\\pi\\approx 3{,}14$).","Calcula el área de un semicírculo de 10 cm de radio ($\\pi\\approx 3{,}14$).","احسب مساحة نصف قرص نصف قطره 10 سم ($\\pi\\approx 3{,}14$)."),solution:r("$3{,}14\\cdot 10^{2}\\mathbin{:}2=314\\mathbin{:}2=157$"),answer:{expected:n(157)}},{id:43,difficulty:"easy",question:a("Azalera ala perimetroa? a) Sukaldeko zorua lauzatu; b) argazki bati markoa jarri; c) belarra erein; d) futbol-zelaia hesiz inguratu.","¿Área o perímetro? a) Embaldosar el suelo de la cocina; b) poner un marco a una foto; c) sembrar césped; d) vallar un campo de fútbol.","مساحة أم محيط؟ أ) تبليط أرضية المطبخ؛ ب) وضع إطار لصورة؛ ج) زرع العشب؛ د) إحاطة ملعب كرة قدم بسياج."),solution:a("a) Azalera; b) perimetroa; c) azalera; d) perimetroa.","a) Área; b) perímetro; c) área; d) perímetro.","أ) مساحة؛ ب) محيط؛ ج) مساحة؛ د) محيط.")},{id:44,difficulty:"medium",question:a("Kalkulatu 12 cm-ko erradioko eta $30^{\\circ}$-ko sektorearen azalera ($\\pi\\approx 3{,}14$).","Calcula el área de un sector de 12 cm de radio y $30^{\\circ}$ ($\\pi\\approx 3{,}14$).","احسب مساحة قطاع نصف قطره 12 سم وزاويته $30^{\\circ}$ ($\\pi\\approx 3{,}14$)."),solution:r("$\\frac{3{,}14\\cdot 12^{2}\\cdot 30}{360}=\\frac{452{,}16}{12}=37{,}68$"),answer:{expected:d("37,68")}},{id:45,difficulty:"medium",question:a("Kalkulatu 7 cm eta 4 cm-ko erradioak dituen koroaren azalera ($\\pi\\approx 3{,}14$).","Calcula el área de la corona de radios 7 cm y 4 cm ($\\pi\\approx 3{,}14$).","احسب مساحة الحلقة التي نصفا قطريها 7 سم و4 سم ($\\pi\\approx 3{,}14$)."),solution:r("$3{,}14\\cdot(49-16)=3{,}14\\cdot 33=103{,}62$"),answer:{expected:d("103,62")}},{id:46,difficulty:"medium",question:a("Kalkulatu 20 cm-ko erradioko zirkunferentzia baten $90^{\\circ}$-ko arkuaren luzera ($\\pi\\approx 3{,}14$).","Calcula la longitud de un arco de $90^{\\circ}$ en una circunferencia de 20 cm de radio ($\\pi\\approx 3{,}14$).","احسب طول قوس $90^{\\circ}$ في دائرة نصف قطرها 20 سم ($\\pi\\approx 3{,}14$)."),solution:r("$\\frac{2\\cdot 3{,}14\\cdot 20\\cdot 90}{360}=\\frac{125{,}6}{4}=31{,}4$"),answer:{expected:d("31,4")}},{id:47,difficulty:"medium",question:a("4 m × 3 m-ko gela bat 20 cm-ko aldeko lauza karratuekin lauzatu nahi da. Zenbat lauza behar dira?","Se quiere embaldosar una habitación de 4 m × 3 m con baldosas cuadradas de 20 cm de lado. ¿Cuántas baldosas hacen falta?","نريد تبليط غرفة 4 م × 3 م ببلاطات مربعة طول ضلعها 20 سم. كم بلاطة نحتاج؟"),solution:r("$4\\cdot 3=12\\qquad 0{,}2\\cdot 0{,}2=0{,}04\\qquad 12\\mathbin{:}0{,}04=300$"),answer:{expected:n(300)}},{id:48,difficulty:"hard",question:a("10 m × 6 m-ko lorategi baten inguruan 1 m zabaleko bide bat egin da. Zein da bidearen azalera (m²)?","Alrededor de un jardín de 10 m × 6 m se ha hecho un camino de 1 m de ancho. ¿Cuál es el área del camino (m²)?","حول حديقة 10 م × 6 م أُنشئ ممر عرضه 1 م. ما مساحة الممر (م²)؟"),solution:a("Kanpoko laukizuzena $12\\times 8$ da: $12\\cdot 8-10\\cdot 6=96-60=36$.","El rectángulo exterior es de $12\\times 8$: $12\\cdot 8-10\\cdot 6=96-60=36$.","المستطيل الخارجي $12\\times 8$: $12\\cdot 8-10\\cdot 6=96-60=36$."),answer:{expected:n(36)}},{id:49,difficulty:"hard",question:a("4 m × 2,5 m-ko horma bat margotu behar da; 1,2 m × 1 m-ko leiho bat du. m² bakoitzak 3 € balio du. Zenbat balio du margotzeak?","Hay que pintar una pared de 4 m × 2,5 m que tiene una ventana de 1,2 m × 1 m. Cada m² cuesta 3 €. ¿Cuánto cuesta pintarla?","يجب طلاء جدار 4 م × 2.5 م فيه نافذة 1.2 م × 1 م. ثمن المتر المربع 3 €. كم تكلفة الطلاء؟"),solution:r("$4\\cdot 2{,}5-1{,}2\\cdot 1=10-1{,}2=8{,}8\\ \\to\\ 8{,}8\\cdot 3=26{,}4$"),answer:{expected:d("26,4")}},{id:50,difficulty:"hard",question:a("8 cm-ko aldeko karratu bati 4 cm-ko erradioko lau zirkulu-laurden kendu zaizkio, bat izkina bakoitzean. Zein da geratzen den azalera? ($\\pi\\approx 3{,}14$)","A un cuadrado de 8 cm de lado se le quitan cuatro cuartos de círculo de 4 cm de radio, uno en cada esquina. ¿Qué área queda? ($\\pi\\approx 3{,}14$)","أُزيلت من مربع طول ضلعه 8 سم أربعة أرباع أقراص نصف قطرها 4 سم، واحد في كل ركن. ما المساحة المتبقية؟ ($\\pi\\approx 3{,}14$)"),solution:a("Lau laurden zirkulu oso bat dira: $8^{2}-3{,}14\\cdot 4^{2}=64-50{,}24=13{,}76$.","Cuatro cuartos son un círculo entero: $8^{2}-3{,}14\\cdot 4^{2}=64-50{,}24=13{,}76$.","أربعة أرباع تساوي قرصًا كاملًا: $8^{2}-3{,}14\\cdot 4^{2}=64-50{,}24=13{,}76$."),answer:{expected:d("13,76")}}]}];function $({game:i}){return i==="race"?t.jsxs("svg",{className:"fraction-v2-game-art",viewBox:"0 0 220 120","aria-hidden":"true",children:[t.jsx("rect",{x:"6",y:"36",width:"208",height:"52",rx:"10",fill:"var(--paper-deep)",stroke:"var(--ink)",strokeWidth:"2"}),t.jsx("line",{x1:"14",y1:"62",x2:"206",y2:"62",stroke:"var(--line)",strokeWidth:"2",strokeDasharray:"8 7"}),t.jsx(k,{color:"var(--coral)",label:"°",x:104,y:20,width:72}),t.jsx(k,{color:"var(--blue)",x:40,y:50,width:62}),t.jsx("text",{x:"110",y:"112",textAnchor:"middle",fontSize:"16",fontWeight:"700",fill:"var(--ink)",direction:"ltr",children:"(n − 2) · 180°"})]}):t.jsx("svg",{className:"fraction-v2-game-art",viewBox:"0 0 220 120","aria-hidden":"true",children:["540°","360°/8","45°","9"].map((c,u)=>t.jsxs("g",{transform:`translate(${14+u*50} ${u%2===0?24:40}) rotate(${u%2===0?-4:4})`,children:[t.jsx("rect",{width:"44",height:"60",rx:"8",fill:u%2===0?"var(--paper-deep)":"var(--blue-tint, #dde7f7)",stroke:"var(--ink)",strokeWidth:"2"}),t.jsx("text",{x:"22",y:"36",textAnchor:"middle",fontSize:c.length>5?9:12,fontWeight:"700",fill:"var(--ink)",direction:"ltr",children:c})]},c))})}const p="matella-figurak-dbh1-game-records",s=[{id:"race",title:{eu:"Irudien lasterketa",es:"Carrera de figuras",ar:"سباق الأشكال"},tagline:{eu:"Erantzun ondo eta azkar: zure autoa aurrera doa, akatsek irrist egiten dute.",es:"Responde bien y rápido: tu coche avanza, los errores le hacen derrapar.",ar:"أجب بدقة وسرعة: تتقدم سيارتك، والأخطاء تجعلها تنزلق."},skills:{eu:"Bost zirkuitu, etapa bakoitzeko bat",es:"Cinco circuitos, uno por etapa",ar:"خمس حلبات، واحدة لكل مرحلة"},levels:[{progressId:18101,stage:"polygons",title:{eu:"Poligonoak",es:"Polígonos",ar:"المضلعات"},description:{eu:"Diagonalak eta angeluak.",es:"Diagonales y ángulos.",ar:"الأقطار والزوايا."}},{progressId:18102,stage:"triangles",title:{eu:"Triangeluak",es:"Triángulos",ar:"المثلثات"},description:{eu:"Isoszeleak, aldeak eta zirkunferentzia.",es:"Isósceles, lados y circunferencia.",ar:"متساوي الساقين والأضلاع والدائرة."}},{progressId:18103,stage:"quadrilaterals",title:{eu:"Laukiak",es:"Cuadriláteros",ar:"الرباعيات"},description:{eu:"Angeluak eta simetria-ardatzak.",es:"Ángulos y ejes de simetría.",ar:"الزوايا ومحاور التناظر."}},{progressId:18104,stage:"circles",title:{eu:"Zirkunferentziak",es:"Circunferencias",ar:"الدوائر"},description:{eu:"Ukitzaileak eta angeluak.",es:"Tangentes y ángulos.",ar:"التماس والزوايا."}},{progressId:18105,stage:"areas",title:{eu:"Azalerak",es:"Áreas",ar:"المساحات"},description:{eu:"Sektoreak, koroak eta L formak.",es:"Sectores, coronas y figuras en L.",ar:"القطاعات والحلقات والأشكال L."}}]},{id:"memory",title:{eu:"Memoria",es:"Memoria",ar:"الذاكرة"},tagline:{eu:"Aurkitu balio bera duten kartak.",es:"Encuentra las cartas que valen lo mismo.",ar:"جد البطاقات ذات القيمة نفسها."},skills:{eu:"Poligonoen angeluak eta diagonalak",es:"Ángulos y diagonales de polígonos",ar:"زوايا المضلعات وأقطارها"},levels:[{progressId:18201,stage:"polygons",title:{eu:"Angeluen batura",es:"Suma de ángulos",ar:"مجموع الزوايا"},description:{eu:"(5 − 2) · 180° ↔ 540°",es:"(5 − 2) · 180° ↔ 540°",ar:"(5 − 2) · 180° ↔ 540°"}},{progressId:18202,stage:"polygons",title:{eu:"Angelu zentrala",es:"Ángulo central",ar:"الزاوية المركزية"},description:{eu:"360° : 8 ↔ 45°",es:"360° : 8 ↔ 45°",ar:"360° : 8 ↔ 45°"}},{progressId:18203,stage:"polygons",title:{eu:"Diagonalak",es:"Diagonales",ar:"الأقطار"},description:{eu:"6 · 3 : 2 ↔ 9",es:"6 · 3 : 2 ↔ 9",ar:"6 · 3 : 2 ↔ 9"}}]}],da=x(s),la={race:"lasterketa",memory:"memoria"};function sa(i){const c=i.match(/\/(?:juegos|jokuak)\/([a-z-]+)$/)?.[1];return c?["carrera","lasterketa"].includes(c)?"race":["memoria","memory"].includes(c)?"memory":"hub":"hub"}const $a={game:s.find(i=>i.id==="race"),generate:v,checkPit:_,parTime:Z,errorTip:i=>A[i??"calculation"],pitPlaceholder:()=>"135",pitUnreadable:{eu:"Idatzi zenbaki bat, adibidez 135 edo 18,84.",es:"Escribe un número, por ejemplo 135 o 18,84.",ar:"اكتب عددًا، مثل 135 أو 18.84."},pitWrongForm:{eu:"Idatzi zenbaki gisa.",es:"Escríbelo como número.",ar:"اكتبه عددًا."}};function ga(i){return t.jsx(h,{...i,rules:$a,art:t.jsx($,{game:"race"})})}const ka=s.find(i=>i.id==="memory"),ma={race:ga,memory:i=>t.jsx(na,{...i,config:{game:ka,art:t.jsx($,{game:"memory"}),pairs:j,createBoard:L}})},pa=s.map(i=>({info:i,art:t.jsx($,{game:i.id}),component:ma[i.id]}));function ba({language:i,pathname:c,openGame:u,completedIds:z,onComplete:f}){return t.jsx(y,{language:i,games:pa,recordsKey:p,title:{eu:"Jolastu eta hobetu zure marka",es:"Juega y mejora tu marca",ar:"العب وحسّن رقمك"},completedIds:z,onComplete:f,mode:sa(c),onModeChange:g=>u(g==="hub"?null:la[g])})}const b=[{id:"polygons",tone:"blue",title:{eu:"Poligonoak: diagonalak eta angeluak",es:"Polígonos: diagonales y ángulos",ar:"المضلعات: الأقطار والزوايا"}},{id:"triangles",tone:"violet",title:{eu:"Triangeluak",es:"Triángulos",ar:"المثلثات"}},{id:"quadrilaterals",tone:"mustard",title:{eu:"Laukiak eta simetria",es:"Cuadriláteros y simetría",ar:"الرباعيات والتناظر"}},{id:"circles",tone:"coral",title:{eu:"Zirkunferentzia eta posizioak",es:"Circunferencia y posiciones",ar:"الدائرة والأوضاع"}},{id:"areas",tone:"green",title:{eu:"Irudi konposatuen azalera",es:"Áreas de figuras compuestas",ar:"مساحات الأشكال المركّبة"}}],e=(i,c,u)=>({eu:i,es:c,ar:u.replace(/\{,\}/g,".")}),o=i=>({eu:i,es:i,ar:i.replace(/\{,\}/g,".")}),za=[{id:"diagonals",stage:"polygons",title:e("Poligono baten diagonalak","Las diagonales de un polígono","أقطار المضلع"),goal:e("Erpin batetik eta poligono osoan zenbat diagonal dauden kalkulatzea.","Calcular cuántas diagonales salen de un vértice y cuántas tiene un polígono.","حساب عدد الأقطار الخارجة من رأس وعدد أقطار المضلع كله."),explanation:e("Diagonala ondoz ondokoak ez diren bi erpin lotzen dituen zuzenkia da. $n$ aldeko poligono batean, erpin bakoitzetik $n-3$ diagonal ateratzen dira: ezin da bere buruarekin lotu, ezta ondoan dituen bi erpinekin ere (horiek aldeak dira). $n$ erpin daudenez, $n\\cdot(n-3)$ marra lirateke, baina diagonal bakoitza bi aldiz zenbatu da (mutur bakoitzetik behin); beraz, diagonal kopurua $\\frac{n\\cdot(n-3)}{2}$ da. Triangeluak ez du diagonalik: $\\frac{3\\cdot 0}{2}=0$.","Una diagonal es un segmento que une dos vértices no consecutivos. En un polígono de $n$ lados, de cada vértice salen $n-3$ diagonales: no puede unirse consigo mismo ni con sus dos vecinos (eso son lados). Como hay $n$ vértices, saldrían $n\\cdot(n-3)$ trazos, pero cada diagonal se ha contado dos veces (una desde cada extremo); por eso el número de diagonales es $\\frac{n\\cdot(n-3)}{2}$. El triángulo no tiene diagonales: $\\frac{3\\cdot 0}{2}=0$.","القطر قطعة تصل بين رأسين غير متتاليين. في مضلع له $n$ ضلعًا يخرج من كل رأس $n-3$ أقطار: فلا يمكن وصله بنفسه ولا بجاريه (فتلك أضلاع). وبما أن هناك $n$ رأسًا ستكون الخطوط $n\\cdot(n-3)$، لكن كل قطر حُسب مرتين (مرة من كل طرف)؛ لذلك عدد الأقطار $\\frac{n\\cdot(n-3)}{2}$. والمثلث ليس له أقطار: $\\frac{3\\cdot 0}{2}=0$."),problem:e("Zenbat diagonal ditu hexagono batek?","¿Cuántas diagonales tiene un hexágono?","كم قطرًا للمسدس؟"),stepsKind:"steps",steps:[{text:e("Erpin batetik: $n-3$.","Desde un vértice: $n-3$.","من رأس واحد: $n-3$."),math:o("$6-3=3$")},{text:e("Erpin guztietatik, zati bi.","Desde todos los vértices, entre dos.","من كل الرؤوس، على اثنين."),math:o("$\\frac{6\\cdot 3}{2}=9$")}],example:o("$n=4\\to 2\\qquad n=5\\to 5\\qquad n=6\\to 9\\qquad n=8\\to 20$"),takeaway:e("Diagonalak: $\\frac{n\\cdot(n-3)}{2}$. Zati bi, bakoitza bi aldiz zenbatzen delako.","Diagonales: $\\frac{n\\cdot(n-3)}{2}$. Entre dos, porque cada una se cuenta dos veces.","الأقطار: $\\frac{n\\cdot(n-3)}{2}$. على اثنين لأن كل قطر يُحسب مرتين."),figure:i=>t.jsx(P,{language:i})},{id:"angle-sum",stage:"polygons",title:e("Barne-angeluen batura","La suma de los ángulos interiores","مجموع الزوايا الداخلية"),goal:e("Poligono baten barne-angeluen batura kalkulatzea eta falta den angelu bat aurkitzea.","Calcular la suma de los ángulos interiores de un polígono y hallar un ángulo que falta.","حساب مجموع الزوايا الداخلية للمضلع وإيجاد زاوية ناقصة."),explanation:e("Erpin bakar batetik diagonal guztiak marrazten badira, $n$ aldeko poligonoa $n-2$ triangelutan banatzen da. Triangelu bakoitzaren angeluek $180^{\\circ}$ egiten dute; beraz, poligonoaren barne-angeluen batura $(n-2)\\cdot 180^{\\circ}$ da: laukian $360^{\\circ}$, pentagonoan $540^{\\circ}$, hexagonoan $720^{\\circ}$. Angelu bat falta bada, kendu ezagunen batura guztizkoari.","Si desde un solo vértice se trazan todas las diagonales, el polígono de $n$ lados queda dividido en $n-2$ triángulos. Los ángulos de cada triángulo suman $180^{\\circ}$; por eso la suma de los ángulos interiores del polígono es $(n-2)\\cdot 180^{\\circ}$: en el cuadrilátero $360^{\\circ}$, en el pentágono $540^{\\circ}$, en el hexágono $720^{\\circ}$. Si falta un ángulo, resta la suma de los conocidos al total.","إذا رُسمت كل الأقطار من رأس واحد انقسم المضلع ذو $n$ ضلعًا إلى $n-2$ مثلثات. مجموع زوايا كل مثلث $180^{\\circ}$؛ لذلك مجموع الزوايا الداخلية للمضلع $(n-2)\\cdot 180^{\\circ}$: في الرباعي $360^{\\circ}$، وفي المخمس $540^{\\circ}$، وفي المسدس $720^{\\circ}$. وإذا نقصت زاوية فاطرح مجموع المعلومة من الكل."),problem:e("Pentagono baten lau angeluak $100^{\\circ}$, $110^{\\circ}$, $120^{\\circ}$ eta $95^{\\circ}$ dira. Zenbat da bosgarrena?","Cuatro ángulos de un pentágono miden $100^{\\circ}$, $110^{\\circ}$, $120^{\\circ}$ y $95^{\\circ}$. ¿Cuánto mide el quinto?","أربع زوايا من مخمس قياساتها $100^{\\circ}$ و$110^{\\circ}$ و$120^{\\circ}$ و$95^{\\circ}$. كم قياس الخامسة؟"),stepsKind:"steps",steps:[{text:e("Batura osoa: $n-2$ triangelu.","La suma total: $n-2$ triángulos.","المجموع الكلي: $n-2$ مثلثات."),math:o("$(5-2)\\cdot 180^{\\circ}=540^{\\circ}$")},{text:e("Batu ezagunak.","Suma los conocidos.","اجمع الزوايا المعلومة."),math:o("$100^{\\circ}+110^{\\circ}+120^{\\circ}+95^{\\circ}=425^{\\circ}$")},{text:e("Kendu.","Resta.","اطرح."),math:o("$540^{\\circ}-425^{\\circ}=115^{\\circ}$")}],example:o("$(4-2)\\cdot 180^{\\circ}=360^{\\circ}\\qquad(6-2)\\cdot 180^{\\circ}=720^{\\circ}$"),takeaway:e("Barne-angeluen batura: $(n-2)\\cdot 180^{\\circ}$.","Suma de los ángulos interiores: $(n-2)\\cdot 180^{\\circ}$.","مجموع الزوايا الداخلية: $(n-2)\\cdot 180^{\\circ}$."),figure:i=>t.jsx(T,{language:i})},{id:"regular-angles",stage:"polygons",title:e("Poligono erregularren angeluak","Los ángulos de los polígonos regulares","زوايا المضلعات المنتظمة"),goal:e("Poligono erregular baten barne-angelua eta angelu zentrala kalkulatzea, eta zein poligonok lauzatzen duten jakitea.","Calcular el ángulo interior y el ángulo central de un polígono regular y saber qué polígonos embaldosan.","حساب الزاوية الداخلية والزاوية المركزية لمضلع منتظم ومعرفة المضلعات التي تُبلِّط."),explanation:e("Poligono erregular batean angelu guztiak berdinak dira; beraz, barne-angelu bakoitza batura zati alde kopurua da: $\\frac{(n-2)\\cdot 180^{\\circ}}{n}$. Pentagono erregularrean $540^{\\circ}\\mathbin{:}5=108^{\\circ}$. Angelu zentrala zentroa eta ondoz ondoko bi erpin lotuz sortzen dena da: zentroaren inguruko $360^{\\circ}$-ak $n$ zati berdinetan banatzen dira, $\\frac{360^{\\circ}}{n}$. Lauza erregularrek zorua hutsunerik gabe estaltzen dute baldin eta barne-angeluak $360^{\\circ}$ zatitzen badu: triangelu aldeberdinak ($60^{\\circ}$), karratuak ($90^{\\circ}$) eta hexagonoak ($120^{\\circ}$) bai; pentagonoak ($108^{\\circ}$) ez.","En un polígono regular todos los ángulos son iguales, así que cada ángulo interior es la suma entre el número de lados: $\\frac{(n-2)\\cdot 180^{\\circ}}{n}$. En el pentágono regular, $540^{\\circ}\\mathbin{:}5=108^{\\circ}$. El ángulo central es el que forman los segmentos que unen el centro con dos vértices consecutivos: los $360^{\\circ}$ alrededor del centro se reparten en $n$ partes iguales, $\\frac{360^{\\circ}}{n}$. Las baldosas regulares cubren el suelo sin huecos si su ángulo interior divide a $360^{\\circ}$: los triángulos equiláteros ($60^{\\circ}$), los cuadrados ($90^{\\circ}$) y los hexágonos ($120^{\\circ}$) sí; los pentágonos ($108^{\\circ}$), no.","في المضلع المنتظم كل الزوايا متساوية، فكل زاوية داخلية تساوي المجموع على عدد الأضلاع: $\\frac{(n-2)\\cdot 180^{\\circ}}{n}$. في المخمس المنتظم $540^{\\circ}\\mathbin{:}5=108^{\\circ}$. والزاوية المركزية هي التي تكوّنها القطعتان الواصلتان بين المركز ورأسين متتاليين: تتوزع $360^{\\circ}$ حول المركز على $n$ أجزاء متساوية، $\\frac{360^{\\circ}}{n}$. وتغطي البلاطات المنتظمة الأرض دون فراغات إذا كانت زاويتها الداخلية تقسم $360^{\\circ}$: المثلثات المتساوية الأضلاع ($60^{\\circ}$) والمربعات ($90^{\\circ}$) والمسدسات ($120^{\\circ}$) نعم؛ والمخمسات ($108^{\\circ}$) لا."),problem:e("Kalkulatu hexagono erregularraren barne-angelua eta angelu zentrala.","Calcula el ángulo interior y el ángulo central del hexágono regular.","احسب الزاوية الداخلية والزاوية المركزية للمسدس المنتظم."),stepsKind:"steps",steps:[{text:e("Batura, zati 6.","La suma, entre 6.","المجموع على 6."),math:o("$\\frac{(6-2)\\cdot 180^{\\circ}}{6}=\\frac{720^{\\circ}}{6}=120^{\\circ}$")},{text:e("Angelu zentrala: $360^{\\circ}$ zati 6.","Ángulo central: $360^{\\circ}$ entre 6.","الزاوية المركزية: $360^{\\circ}$ على 6."),math:o("$\\frac{360^{\\circ}}{6}=60^{\\circ}$")},{text:e("Hiru hexagono erpin batean: lauzatzen du.","Tres hexágonos en un vértice: embaldosa.","ثلاثة مسدسات عند رأس: يُبلِّط."),math:o("$3\\cdot 120^{\\circ}=360^{\\circ}$")}],example:o("$\\frac{360^{\\circ}}{5}=72^{\\circ}\\qquad\\frac{540^{\\circ}}{5}=108^{\\circ}$"),takeaway:e("Barne-angelua: $\\frac{(n-2)\\cdot 180^{\\circ}}{n}$. Angelu zentrala: $\\frac{360^{\\circ}}{n}$.","Ángulo interior: $\\frac{(n-2)\\cdot 180^{\\circ}}{n}$. Ángulo central: $\\frac{360^{\\circ}}{n}$.","الزاوية الداخلية: $\\frac{(n-2)\\cdot 180^{\\circ}}{n}$. الزاوية المركزية: $\\frac{360^{\\circ}}{n}$."),figure:i=>t.jsx(S,{language:i})},{id:"triangle-exists",stage:"triangles",title:e("Noiz eraiki daiteke triangelu bat?","¿Cuándo se puede construir un triángulo?","متى يمكن إنشاء مثلث؟"),goal:e("Hiru zuzenkirekin edo bi angelurekin triangelu bat eraiki daitekeen erabakitzea.","Decidir si con tres segmentos o con dos ángulos se puede construir un triángulo.","تحديد ما إذا كان يمكن إنشاء مثلث بثلاث قطع أو بزاويتين."),explanation:e("Hiru makilarekin ez da beti triangelu bat egiten. Alde bakoitzak beste bien batura baino txikiagoa izan behar du: hori da desberdintza triangeluarra. Nahikoa da alde handiena egiaztatzea: 3, 5 eta 7 cm-rekin, $7<3+5=8$, eta triangelua eraiki daiteke; 3, 4 eta 8 cm-rekin, $8>3+4=7$, eta bi alde txikiek ez dute elkar ukitzen. $7=3+4$ bada, aldeak zuzen baten gainean geratzen dira. Angeluekin ere muga bat dago: hirurek $180^{\\circ}$ egin behar dute, beraz bi angeluk $180^{\\circ}$ baino gutxiago batu behar dute ($95^{\\circ}$ eta $88^{\\circ}$-rekin ez da posible).","Con tres palos no siempre se forma un triángulo. Cada lado tiene que ser menor que la suma de los otros dos: es la desigualdad triangular. Basta comprobar el lado mayor: con 3, 5 y 7 cm, $7<3+5=8$, y el triángulo se puede construir; con 3, 4 y 8 cm, $8>3+4=7$, y los dos lados pequeños no llegan a tocarse. Si $7=3+4$, los lados quedan aplastados sobre una recta. Con los ángulos también hay un límite: los tres suman $180^{\\circ}$, así que dos ángulos tienen que sumar menos de $180^{\\circ}$ (con $95^{\\circ}$ y $88^{\\circ}$ no es posible).","لا تكوّن ثلاثة أعواد مثلثًا دائمًا. يجب أن يكون كل ضلع أصغر من مجموع الضلعين الآخرين: هذه هي متباينة المثلث. ويكفي التحقق من الضلع الأكبر: مع 3 و5 و7 سم، $7<3+5=8$، فيمكن إنشاء المثلث؛ ومع 3 و4 و8 سم، $8>3+4=7$، فلا يلتقي الضلعان الصغيران. وإذا كان $7=3+4$ انطبق الضلعان على مستقيم. وللزوايا حدّ أيضًا: مجموع الثلاث $180^{\\circ}$، فيجب أن يكون مجموع زاويتين أقل من $180^{\\circ}$ (مع $95^{\\circ}$ و$88^{\\circ}$ لا يمكن)."),problem:e("Triangelu bat eraiki daiteke 4, 6 eta 11 cm-ko zuzenkiekin?","¿Se puede construir un triángulo con segmentos de 4, 6 y 11 cm?","هل يمكن إنشاء مثلث بقطع أطوالها 4 و6 و11 سم؟"),stepsKind:"steps",steps:[{text:e("Alde handiena: 11.","El lado mayor: 11.","الضلع الأكبر: 11.")},{text:e("Batu beste biak.","Suma los otros dos.","اجمع الآخرين."),math:o("$4+6=10$")},{text:e("$11>10$: ez da eraikitzen.","$11>10$: no se puede construir.","$11>10$: لا يمكن إنشاؤه.")}],example:o("$7<3+5\\qquad 8>3+4$"),takeaway:e("Alde handiena < beste bien batura. Bi angelu < $180^{\\circ}$.","Lado mayor < suma de los otros dos. Dos ángulos < $180^{\\circ}$.","الضلع الأكبر < مجموع الآخرين. زاويتان < $180^{\\circ}$."),figure:i=>t.jsx(I,{language:i})},{id:"side-angle",stage:"triangles",title:e("Aldeak eta angeluak","Lados y ángulos","الأضلاع والزوايا"),goal:e("Alde handienaren aurrean angelu handiena dagoela jakitea eta triangelu isoszeleen angeluak kalkulatzea.","Saber que frente al lado mayor está el ángulo mayor y calcular los ángulos de un triángulo isósceles.","معرفة أن الزاوية الكبرى تقابل الضلع الأكبر وحساب زوايا المثلث المتساوي الساقين."),explanation:e("Triangelu batean, alde handienaren aurrean angelu handiena dago, eta alde txikienaren aurrean, txikiena. Bi alde berdinak badira (isoszelea), haien aurreko bi angeluak ere berdinak dira: oinarriko angeluak. Hiru aldeak berdinak badira (aldeberdina), hiru angeluak berdinak dira: $180^{\\circ}\\mathbin{:}3=60^{\\circ}$, triangeluaren tamaina edozein dela ere. Isoszele batean erpineko angelua $\\hat{A}$ bada, oinarriko bakoitza $(180^{\\circ}-\\hat{A})\\mathbin{:}2$ da.","En un triángulo, frente al lado mayor está el ángulo mayor, y frente al lado menor, el menor. Si dos lados son iguales (isósceles), los dos ángulos opuestos a ellos también son iguales: los ángulos de la base. Si los tres lados son iguales (equilátero), los tres ángulos son iguales: $180^{\\circ}\\mathbin{:}3=60^{\\circ}$, sea cual sea el tamaño del triángulo. En un isósceles, si el ángulo desigual es $\\hat{A}$, cada ángulo de la base es $(180^{\\circ}-\\hat{A})\\mathbin{:}2$.","في المثلث تقابل الزاويةُ الكبرى الضلعَ الأكبر، وتقابل الصغرى الضلعَ الأصغر. وإذا تساوى ضلعان (متساوي الساقين) تساوت الزاويتان المقابلتان لهما: زاويتا القاعدة. وإذا تساوت الأضلاع الثلاثة (متساوي الأضلاع) تساوت الزوايا الثلاث: $180^{\\circ}\\mathbin{:}3=60^{\\circ}$ مهما كان حجم المثلث. وفي متساوي الساقين، إذا كانت زاوية الرأس $\\hat{A}$ فكل زاوية من زاويتي القاعدة تساوي $(180^{\\circ}-\\hat{A})\\mathbin{:}2$."),problem:e("Triangelu isoszele baten erpineko angelua $40^{\\circ}$ da. Zenbat da oinarriko angelu bakoitza?","El ángulo desigual de un triángulo isósceles mide $40^{\\circ}$. ¿Cuánto mide cada ángulo de la base?","زاوية الرأس في مثلث متساوي الساقين $40^{\\circ}$. كم قياس كل زاوية من زاويتي القاعدة؟"),stepsKind:"steps",steps:[{text:e("Kendu $180^{\\circ}$-ri.","Réstalo de $180^{\\circ}$.","اطرحها من $180^{\\circ}$."),math:o("$180^{\\circ}-40^{\\circ}=140^{\\circ}$")},{text:e("Bi angelu berdin: zati bi.","Dos ángulos iguales: entre dos.","زاويتان متساويتان: على اثنين."),math:o("$140^{\\circ}\\mathbin{:}2=70^{\\circ}$")}],example:o("$b<a<c\\ \\to\\ \\hat{B}<\\hat{A}<\\hat{C}$"),takeaway:e("Alde handiena ↔ angelu handiena. Alde berdinak ↔ angelu berdinak.","Lado mayor ↔ ángulo mayor. Lados iguales ↔ ángulos iguales.","الضلع الأكبر ↔ الزاوية الكبرى. أضلاع متساوية ↔ زوايا متساوية."),figure:i=>t.jsx(w,{language:i})},{id:"centers",stage:"triangles",title:e("Puntu nabarmenak eta zirkunferentziak","Puntos notables y circunferencias","النقاط المهمة والدوائر"),goal:e("Zirkunferentzia zirkunskribatua eta inskribatua ezagutzea eta puntu nabarmenak non dauden jakitea triangelu motaren arabera.","Conocer las circunferencias circunscrita e inscrita y saber dónde caen los puntos notables según el tipo de triángulo.","معرفة الدائرتين المحيطة والداخلية ومعرفة مواقع النقاط المهمة حسب نوع المثلث."),explanation:e("Erdibitzaileak zirkunzentroan ebakitzen dira, eta puntu hori hiru erpinetatik distantzia berera dago: zentro hori duen zirkunferentzia hiru erpinetatik pasatzen da (zirkunskribatua). Erdikariak inzentroan ebakitzen dira, hiru aldeetatik distantzia berera: hor zentratutako zirkunferentziak hiru aldeak ukitzen ditu barrutik (inskribatua). Zirkunzentroaren lekuak triangelu mota salatzen du: angelu-zorrotzean barruan dago; angeluzuzenean, hipotenusaren erdiko puntuan; angelu-kamutsean, kanpoan. Ortozentroarekin gauza bera gertatzen da, eta angeluzuzenean angelu zuzeneko erpinean dago. Barizentroa eta inzentroa beti daude barruan. Triangelu aldeberdinean lau puntuak bat datoz.","Las mediatrices se cortan en el circuncentro, y ese punto está a la misma distancia de los tres vértices: la circunferencia con ese centro pasa por los tres vértices (circunscrita). Las bisectrices se cortan en el incentro, a la misma distancia de los tres lados: la circunferencia centrada allí toca los tres lados por dentro (inscrita). La posición del circuncentro delata el tipo de triángulo: en el acutángulo está dentro; en el rectángulo, en el punto medio de la hipotenusa; en el obtusángulo, fuera. Con el ortocentro pasa lo mismo, y en el rectángulo está en el vértice del ángulo recto. El baricentro y el incentro siempre están dentro. En el triángulo equilátero los cuatro puntos coinciden.","تتقاطع المحاور في مركز الدائرة المحيطة، وتلك النقطة على البعد نفسه من الرؤوس الثلاثة: فالدائرة التي مركزها هناك تمر بالرؤوس الثلاثة (المحيطة). وتتقاطع المنصفات في مركز الدائرة الداخلية، على البعد نفسه من الأضلاع الثلاثة: فالدائرة التي مركزها هناك تمس الأضلاع الثلاثة من الداخل (الداخلية). ويكشف موقع مركز الدائرة المحيطة نوع المثلث: في الحاد الزوايا داخله؛ وفي القائم في منتصف الوتر؛ وفي المنفرج خارجه. والأمر نفسه مع ملتقى الارتفاعات، وهو في القائم عند رأس الزاوية القائمة. أما مركز الثقل ومركز الدائرة الداخلية فداخل المثلث دائمًا. وفي المثلث المتساوي الأضلاع تنطبق النقاط الأربع."),stepsKind:"facts",steps:[{title:e("Zirkunzentroa","Circuncentro","مركز الدائرة المحيطة"),text:e("Erdibitzaileak. Erpinetatik pasatzen den zirkunferentzia.","Mediatrices. Circunferencia que pasa por los vértices.","المحاور. دائرة تمر بالرؤوس.")},{title:e("Inzentroa","Incentro","مركز الدائرة الداخلية"),text:e("Erdikariak. Aldeak ukitzen dituen zirkunferentzia.","Bisectrices. Circunferencia que toca los lados.","المنصفات. دائرة تمس الأضلاع.")},{title:e("Non dago?","¿Dónde cae?","أين يقع؟"),text:e("Zorrotza: barruan. Zuzena: hipotenusan. Kamutsa: kanpoan.","Acutángulo: dentro. Rectángulo: en la hipotenusa. Obtusángulo: fuera.","حاد: داخله. قائم: على الوتر. منفرج: خارجه.")}],example:e("Angeluzuzena: zirkunzentroa = hipotenusaren erdia","Rectángulo: circuncentro = punto medio de la hipotenusa","القائم: مركز الدائرة المحيطة = منتصف الوتر"),takeaway:e("Zirkunskribatua erpinetatik; inskribatua aldeak ukituz.","Circunscrita, por los vértices; inscrita, tocando los lados.","المحيطة تمر بالرؤوس؛ والداخلية تمس الأضلاع."),figure:i=>t.jsx(B,{language:i})},{id:"quad-diagonals",stage:"quadrilaterals",title:e("Laukien diagonalak","Las diagonales de los cuadriláteros","أقطار الرباعيات"),goal:e("Lauki bat bere diagonalen propietateen bidez ezagutzea.","Reconocer un cuadrilátero por las propiedades de sus diagonales.","التعرّف إلى الرباعي من خصائص قطريه."),explanation:e("Laukiak diagonalen bidez ere bereiz daitezke. Paralelogramo guztietan diagonalak beren erdiko puntuan ebakitzen dira. Gainera, laukizuzenean berdinak dira; erronboan, perpendikularrak; eta karratuan, berdinak eta perpendikularrak. Erronboidean ez berdinak ez perpendikularrak. Paralelogramoak ez diren laukietan ere badira kasu bereziak: kometan (trapezoide bat) diagonalak perpendikularrak dira, baina bakarra erdibitzen da; trapezio isoszelean diagonalak berdinak dira. Ariketa polita: bi zuzenki gurutzatu erdian eta lotu muturrak; zuzenkien arabera irudi bat edo beste lortzen da.","Los cuadriláteros también se distinguen por sus diagonales. En todos los paralelogramos las diagonales se cortan en su punto medio. Además, en el rectángulo son iguales; en el rombo, perpendiculares; y en el cuadrado, iguales y perpendiculares. En el romboide no son ni iguales ni perpendiculares. Fuera de los paralelogramos también hay casos especiales: en la cometa (un trapezoide) las diagonales son perpendiculares, pero solo una queda partida por la mitad; en el trapecio isósceles las diagonales son iguales. Un juego: cruza dos segmentos por su mitad y une los extremos; según cómo sean los segmentos, sale una figura u otra.","تتميز الرباعيات بأقطارها أيضًا. في كل متوازيات الأضلاع ينصّف القطران كلٌّ منهما الآخر. وفوق ذلك هما متساويان في المستطيل؛ ومتعامدان في المعيّن؛ ومتساويان ومتعامدان في المربع. وفي متوازي الأضلاع العادي لا متساويان ولا متعامدان. وخارج متوازيات الأضلاع حالات خاصة أيضًا: في الطائرة الورقية (رباعي عام) القطران متعامدان لكن واحدًا منهما فقط يُنصَّف؛ وفي شبه المنحرف المتساوي الساقين القطران متساويان. لعبة: صالِب قطعتين من منتصفيهما وصِل أطرافهما؛ فحسب القطعتين ينتج شكل أو آخر."),stepsKind:"facts",steps:[{title:e("Erdian ebakitzen dira","Se cortan en el punto medio","ينصّف كلٌّ منهما الآخر"),text:e("Paralelogramo guztiak.","Todos los paralelogramos.","كل متوازيات الأضلاع.")},{title:e("Berdinak","Iguales","متساويان"),text:e("Laukizuzena, karratua eta trapezio isoszelea.","Rectángulo, cuadrado y trapecio isósceles.","المستطيل والمربع وشبه المنحرف المتساوي الساقين.")},{title:e("Perpendikularrak","Perpendiculares","متعامدان"),text:e("Erronboa, karratua eta kometa.","Rombo, cuadrado y cometa.","المعيّن والمربع والطائرة الورقية.")}],example:e("Erdian + berdinak + perpendikularrak → karratua","Punto medio + iguales + perpendiculares → cuadrado","التنصيف + التساوي + التعامد ← مربع"),takeaway:e("Erdian: paralelogramoa. Berdinak: laukizuzena. Perpendikularrak: erronboa. Biak: karratua.","Punto medio: paralelogramo. Iguales: rectángulo. Perpendiculares: rombo. Las dos: cuadrado.","التنصيف: متوازي أضلاع. التساوي: مستطيل. التعامد: معيّن. الاثنان: مربع."),figure:i=>t.jsx(D,{language:i})},{id:"quad-angles",stage:"quadrilaterals",title:e("Laukien angeluak","Los ángulos de los cuadriláteros","زوايا الرباعيات"),goal:e("Paralelogramo eta trapezioetan falta diren angeluak kalkulatzea.","Calcular los ángulos que faltan en paralelogramos y trapecios.","حساب الزوايا الناقصة في متوازيات الأضلاع وأشباه المنحرف."),explanation:e("Edozein laukitan angeluen batura $360^{\\circ}$ da. Paralelogramoetan, aurkako angeluak berdinak dira, eta ondoz ondokoek $180^{\\circ}$ egiten dute (betegarriak dira), alde paraleloen artean daudelako. Beraz, angelu bat jakinda, guztiak dakizkigu: $70^{\\circ}$ bada, besteak $110^{\\circ}$, $70^{\\circ}$ eta $110^{\\circ}$. Trapezioetan, alde ez-paralelo bereko bi angeluek $180^{\\circ}$ egiten dute; trapezio isoszelean, gainera, oinarri bereko angeluak berdinak dira.","En cualquier cuadrilátero los ángulos suman $360^{\\circ}$. En los paralelogramos, los ángulos opuestos son iguales y los consecutivos suman $180^{\\circ}$ (son suplementarios), porque están entre lados paralelos. Así que, sabiendo un ángulo, se saben todos: si uno mide $70^{\\circ}$, los otros miden $110^{\\circ}$, $70^{\\circ}$ y $110^{\\circ}$. En los trapecios, los dos ángulos de un mismo lado no paralelo suman $180^{\\circ}$; en el trapecio isósceles, además, los ángulos de una misma base son iguales.","في أي رباعي مجموع الزوايا $360^{\\circ}$. وفي متوازيات الأضلاع تتساوى الزوايا المتقابلة، ومجموع كل زاويتين متتاليتين $180^{\\circ}$ (متكاملتان) لأنهما بين ضلعين متوازيين. فإذا عرفنا زاوية عرفنا الجميع: إذا كانت $70^{\\circ}$ فالأخريات $110^{\\circ}$ و$70^{\\circ}$ و$110^{\\circ}$. وفي أشباه المنحرف مجموع زاويتي الضلع غير الموازي نفسه $180^{\\circ}$؛ وفي شبه المنحرف المتساوي الساقين تتساوى أيضًا زاويتا القاعدة نفسها."),problem:e("Erronboide baten angelu bat $65^{\\circ}$ da. Zenbat dira besteak?","Un ángulo de un romboide mide $65^{\\circ}$. ¿Cuánto miden los otros?","زاوية في متوازي أضلاع قياسها $65^{\\circ}$. كم قياس الأخريات؟"),stepsKind:"steps",steps:[{text:e("Aurkakoa, berdina.","El opuesto, igual.","المقابلة مساوية."),math:o("$65^{\\circ}$")},{text:e("Ondokoak, betegarriak.","Los consecutivos, suplementarios.","المتتاليتان متكاملتان."),math:o("$180^{\\circ}-65^{\\circ}=115^{\\circ}$")},{text:e("Egiaztatu batura.","Comprueba la suma.","تحقّق من المجموع."),math:o("$65^{\\circ}+115^{\\circ}+65^{\\circ}+115^{\\circ}=360^{\\circ}$")}],example:o("$70^{\\circ}+110^{\\circ}=180^{\\circ}$"),takeaway:e("Paralelogramoa: aurkakoak berdinak, ondokoek $180^{\\circ}$.","Paralelogramo: opuestos iguales, consecutivos suman $180^{\\circ}$.","متوازي الأضلاع: المتقابلة متساوية والمتتالية مجموعها $180^{\\circ}$."),figure:i=>t.jsx(K,{language:i})},{id:"symmetry",stage:"quadrilaterals",title:e("Simetria-ardatzak","Ejes de simetría","محاور التناظر"),goal:e("Irudi lau baten simetria-ardatzak aurkitzea eta zenbatzea.","Encontrar y contar los ejes de simetría de una figura plana.","إيجاد محاور تناظر شكل مستوٍ وعدّها."),explanation:e("Simetria-ardatza irudia bi zati berdinetan banatzen duen zuzena da, ispilu bat bezala: irudia ardatzetik tolestuz gero, bi zatiak bat datoz. Karratuak 4 ardatz ditu (2 erdibideak eta 2 diagonalak); laukizuzenak 2 eta erronboak 2 (laukizuzenean erdibideak, erronboan diagonalak); trapezio isoszeleak eta kometak 1; erronboideak bat ere ez. $n$ aldeko poligono erregular batek $n$ ardatz ditu, eta ondoz ondoko bi ardatzek $\\frac{180^{\\circ}}{n}$ eratzen dute. Zirkuluak infinitu ditu: zentrotik pasatzen den zuzen oro.","Un eje de simetría es una recta que divide la figura en dos partes iguales, como un espejo: si se dobla la figura por el eje, las dos partes coinciden. El cuadrado tiene 4 ejes (las 2 medianas y las 2 diagonales); el rectángulo, 2, y el rombo, 2 (en el rectángulo, las medianas; en el rombo, las diagonales); el trapecio isósceles y la cometa, 1; el romboide, ninguno. Un polígono regular de $n$ lados tiene $n$ ejes, y dos ejes contiguos forman $\\frac{180^{\\circ}}{n}$. El círculo tiene infinitos: cualquier recta que pase por el centro.","محور التناظر مستقيم يقسم الشكل إلى جزأين متطابقين كالمرآة: إذا طُوي الشكل على المحور انطبق الجزآن. للمربع 4 محاور (المستقيمان الواصلان بين منتصفات الأضلاع المتقابلة والقطران)؛ وللمستطيل 2 وللمعيّن 2 (في المستطيل الواصلان بين المنتصفات، وفي المعيّن القطران)؛ ولشبه المنحرف المتساوي الساقين وللطائرة الورقية محور واحد؛ ولمتوازي الأضلاع العادي لا شيء. وللمضلع المنتظم ذي $n$ ضلعًا $n$ محاور، وبين كل محورين متجاورين $\\frac{180^{\\circ}}{n}$. وللدائرة عدد لا نهائي: كل مستقيم يمر بالمركز."),problem:e("Zenbat simetria-ardatz ditu pentagono erregular batek, eta zer angelu eratzen dute ondoz ondoko bik?","¿Cuántos ejes de simetría tiene un pentágono regular y qué ángulo forman dos contiguos?","كم محور تناظر للمخمس المنتظم، وما الزاوية بين محورين متجاورين؟"),stepsKind:"steps",steps:[{text:e("Poligono erregularra: $n$ ardatz.","Polígono regular: $n$ ejes.","مضلع منتظم: $n$ محاور."),math:o("$5$")},{text:e("Ardatzek $180^{\\circ}$ banatzen dute.","Los ejes se reparten $180^{\\circ}$.","تتقاسم المحاور $180^{\\circ}$."),math:o("$180^{\\circ}\\mathbin{:}5=36^{\\circ}$")}],example:o("$\\square\\to 4\\qquad\\triangle\\to 3\\qquad\\bigcirc\\to\\infty$"),takeaway:e("Erregularra: $n$ ardatz, $\\frac{180^{\\circ}}{n}$-ko tartearekin.","Regular: $n$ ejes, separados $\\frac{180^{\\circ}}{n}$.","المنتظم: $n$ محاور، بينها $\\frac{180^{\\circ}}{n}$."),figure:i=>t.jsx(F,{language:i})},{id:"line-circle",stage:"circles",title:e("Zuzena eta zirkunferentzia","Recta y circunferencia","المستقيم والدائرة"),goal:e("Zuzen baten eta zirkunferentzia baten posizio erlatiboa zentrorako distantziaren bidez erabakitzea.","Decidir la posición relativa de una recta y una circunferencia con la distancia al centro.","تحديد الوضع النسبي لمستقيم ودائرة بواسطة البعد عن المركز."),explanation:e("Konparatu zentrotik zuzenerako distantzia $d$ erradioarekin $r$. $d>r$ bada, zuzena kanpokoa da: ez du zirkunferentzia ukitzen. $d=r$ bada, ukitzailea da: puntu bakar batean ukitzen du, eta puntu horretako erradioarekiko perpendikularra da. $d<r$ bada, ebakitzailea da: bi puntutan ebakitzen du, eta haien arteko zatia korda bat da. Zentrotik pasatzen den ebakitzailearen korda diametroa da, kordarik luzeena.","Compara la distancia $d$ del centro a la recta con el radio $r$. Si $d>r$, la recta es exterior: no toca la circunferencia. Si $d=r$, es tangente: la toca en un solo punto y es perpendicular al radio en ese punto. Si $d<r$, es secante: la corta en dos puntos, y el trozo entre ellos es una cuerda. La cuerda de la secante que pasa por el centro es el diámetro, la cuerda más larga.","قارن البعد $d$ من المركز إلى المستقيم بنصف القطر $r$. إذا كان $d>r$ فالمستقيم خارجي: لا يمس الدائرة. وإذا كان $d=r$ فهو مماس: يمسها في نقطة واحدة ويعامد نصف القطر عندها. وإذا كان $d<r$ فهو قاطع: يقطعها في نقطتين، والجزء بينهما وتر. ووتر القاطع المار بالمركز هو القطر، أطول الأوتار."),problem:e("Zirkunferentzia baten erradioa 5 cm da. Nolakoak dira zentrotik 3 cm, 5 cm eta 8 cm-ra dauden zuzenak?","Una circunferencia tiene 5 cm de radio. ¿Cómo son las rectas que pasan a 3 cm, 5 cm y 8 cm del centro?","نصف قطر دائرة 5 سم. كيف تكون المستقيمات التي تبعد عن المركز 3 سم و5 سم و8 سم؟"),stepsKind:"steps",steps:[{text:e("3 < 5: ebakitzailea.","3 < 5: secante.","3 < 5: قاطع.")},{text:e("5 = 5: ukitzailea.","5 = 5: tangente.","5 = 5: مماس.")},{text:e("8 > 5: kanpokoa.","8 > 5: exterior.","8 > 5: خارجي.")}],example:o("$d<r\\qquad d=r\\qquad d>r$"),takeaway:e("$d<r$ ebakitzailea, $d=r$ ukitzailea, $d>r$ kanpokoa.","$d<r$ secante, $d=r$ tangente, $d>r$ exterior.","$d<r$ قاطع، $d=r$ مماس، $d>r$ خارجي."),figure:i=>t.jsx(R,{language:i})},{id:"two-circles",stage:"circles",title:e("Bi zirkunferentziaren posizioak","Posiciones de dos circunferencias","أوضاع دائرتين"),goal:e("Bi zirkunferentziaren posizio erlatiboa zentroen arteko distantziaz eta erradioez erabakitzea.","Decidir la posición relativa de dos circunferencias con la distancia entre centros y los radios.","تحديد الوضع النسبي لدائرتين بالبعد بين المركزين ونصفي القطرين."),explanation:e("Izan bitez $r_1$ eta $r_2$ erradioak ($r_1$ handiena) eta $d$ zentroen arteko distantzia. Konparatu $d$ erradioen baturarekin eta kendurarekin. $d>r_1+r_2$: kanpokoak, ez dira ukitzen. $d=r_1+r_2$: kanpotik ukitzaileak. $r_1-r_2<d<r_1+r_2$: ebakitzaileak, bi puntutan ebakitzen dira. $d=r_1-r_2$: barrutik ukitzaileak. $d<r_1-r_2$: barnekoak, txikia handiaren barruan dago ukitu gabe. $d=0$: zentrokideak.","Sean $r_1$ y $r_2$ los radios ($r_1$ el mayor) y $d$ la distancia entre los centros. Compara $d$ con la suma y con la resta de los radios. $d>r_1+r_2$: exteriores, no se tocan. $d=r_1+r_2$: tangentes exteriores. $r_1-r_2<d<r_1+r_2$: secantes, se cortan en dos puntos. $d=r_1-r_2$: tangentes interiores. $d<r_1-r_2$: interiores, la pequeña está dentro de la grande sin tocarla. $d=0$: concéntricas.","ليكن $r_1$ و$r_2$ نصفي القطرين ($r_1$ الأكبر) و$d$ البعد بين المركزين. قارن $d$ بمجموع نصفي القطرين وبفرقهما. $d>r_1+r_2$: متباعدتان لا تتلامسان. $d=r_1+r_2$: متماستان من الخارج. $r_1-r_2<d<r_1+r_2$: متقاطعتان في نقطتين. $d=r_1-r_2$: متماستان من الداخل. $d<r_1-r_2$: متداخلتان، الصغرى داخل الكبرى دون تماس. $d=0$: متحدتا المركز."),problem:e("Bi zirkunferentziaren erradioak 7 cm eta 4 cm dira, eta zentroak 10 cm-ra daude. Nolakoak dira?","Dos circunferencias tienen radios de 7 cm y 4 cm, y sus centros están a 10 cm. ¿Cómo son?","نصفا قطري دائرتين 7 سم و4 سم، والبعد بين مركزيهما 10 سم. كيف هما؟"),stepsKind:"steps",steps:[{text:e("Batura eta kendura.","La suma y la resta.","المجموع والفرق."),math:o("$7+4=11\\qquad 7-4=3$")},{text:e("Konparatu $d$.","Compara $d$.","قارن $d$."),math:o("$3<10<11$")},{text:e("Ebakitzaileak dira.","Son secantes.","هما متقاطعتان.")}],example:o("$d=r_1+r_2\\qquad d=r_1-r_2$"),takeaway:e("Konparatu $d$ honekin: $r_1+r_2$ eta $r_1-r_2$.","Compara $d$ con $r_1+r_2$ y con $r_1-r_2$.","قارن $d$ بـ$r_1+r_2$ وبـ$r_1-r_2$."),figure:i=>t.jsx(U,{language:i})},{id:"circle-angles",stage:"circles",title:e("Angeluak zirkunferentzian eta irudi zirkularrak","Ángulos en la circunferencia y figuras circulares","الزوايا في الدائرة والأشكال الدائرية"),goal:e("Angelu zentrala eta inskribatua bereiztea eta irudi zirkularrak izendatzea.","Distinguir el ángulo central y el inscrito y nombrar las figuras circulares.","التمييز بين الزاوية المركزية والمحيطية وتسمية الأشكال الدائرية."),explanation:e("Angelu zentralak erpina zentroan du, eta haren aldeak erradioak dira. Angelu inskribatuak erpina zirkunferentzian du, eta haren aldeak kordak dira. Arku bera hartzen badute, inskribatua zentralaren erdia da: zentrala $100^{\\circ}$ bada, inskribatua $50^{\\circ}$. Diametro baten gaineko angelu inskribatu oro zuzena da, zentrala $180^{\\circ}$ delako. Zirkuluaren zatiek izenak dituzte: sektore zirkularra (bi erradio eta arku bat, pizza-zati bat bezala), segmentu zirkularra (korda bat eta arku bat), koroa zirkularra (zentro bereko bi zirkunferentziaren arteko eraztuna) eta trapezio zirkularra (koroaren zati bat).","El ángulo central tiene el vértice en el centro, y sus lados son radios. El ángulo inscrito tiene el vértice en la circunferencia, y sus lados son cuerdas. Si abarcan el mismo arco, el inscrito mide la mitad que el central: si el central mide $100^{\\circ}$, el inscrito mide $50^{\\circ}$. Todo ángulo inscrito que abarca un diámetro es recto, porque el central mide $180^{\\circ}$. Las partes del círculo tienen nombre: sector circular (dos radios y un arco, como una porción de pizza), segmento circular (una cuerda y un arco), corona circular (el anillo entre dos circunferencias con el mismo centro) y trapecio circular (un trozo de la corona).","رأس الزاوية المركزية في المركز وضلعاها نصفا قطرين. ورأس الزاوية المحيطية على الدائرة وضلعاها وتران. وإذا حصرتا القوس نفسه فالمحيطية نصف المركزية: إذا كانت المركزية $100^{\\circ}$ فالمحيطية $50^{\\circ}$. وكل زاوية محيطية تحصر قطرًا قائمة، لأن المركزية $180^{\\circ}$. ولأجزاء القرص أسماء: القطاع الدائري (نصفا قطرين وقوس، كقطعة بيتزا)، والقطعة الدائرية (وتر وقوس)، والحلقة الدائرية (ما بين دائرتين لهما المركز نفسه)، وشبه المنحرف الدائري (جزء من الحلقة)."),problem:e("Angelu inskribatu batek $35^{\\circ}$ ditu. Zenbat ditu arku bera hartzen duen angelu zentralak?","Un ángulo inscrito mide $35^{\\circ}$. ¿Cuánto mide el central que abarca el mismo arco?","زاوية محيطية قياسها $35^{\\circ}$. كم قياس الزاوية المركزية التي تحصر القوس نفسه؟"),stepsKind:"steps",steps:[{text:e("Zentrala inskribatuaren bikoitza da.","El central es el doble del inscrito.","المركزية ضعف المحيطية."),math:o("$2\\cdot 35^{\\circ}=70^{\\circ}$")}],example:o("$\\hat{P}=\\frac{\\hat{O}}{2}\\qquad 50^{\\circ}=\\frac{100^{\\circ}}{2}$"),takeaway:e("Inskribatua = zentrala : 2. Diametroaren gainean: $90^{\\circ}$.","Inscrito = central : 2. Sobre un diámetro: $90^{\\circ}$.","المحيطية = المركزية : 2. على قطر: $90^{\\circ}$."),figure:i=>t.jsx(O,{language:i})},{id:"composite",stage:"areas",title:e("Irudi konposatuak","Figuras compuestas","الأشكال المركّبة"),goal:e("Irudi konposatu baten azalera irudi ezagunetan zatituz edo kenduz kalkulatzea.","Calcular el área de una figura compuesta descomponiéndola en figuras conocidas o restando.","حساب مساحة شكل مركّب بتقسيمه إلى أشكال معروفة أو بالطرح."),explanation:e("Irudi konposatu baten azalera kalkulatzeko, bi bide daude. Batu: zatitu irudia formula ezaguneko zatitan (laukizuzenak, triangeluak, trapezioak, zirkulu-erdiak…) eta batu haien azalerak. Kendu: irudi handiago bat osatu eta kendu soberan dagoena; adibidez, zulo bat duen ohol baten azalera = oholaren azalera − zuloaren azalera. Kontuz neurriekin: zati batzuen neurriak beste aldeetatik atera behar dira, eta unitate karratuak erabili behar dira beti.","Para calcular el área de una figura compuesta hay dos caminos. Sumar: divide la figura en piezas de fórmula conocida (rectángulos, triángulos, trapecios, semicírculos…) y suma sus áreas. Restar: completa una figura mayor y quita lo que sobra; por ejemplo, el área de una tabla con un agujero = área de la tabla − área del agujero. Cuidado con las medidas: algunas hay que deducirlas de los otros lados, y el resultado siempre va en unidades cuadradas.","لحساب مساحة شكل مركّب طريقان. الجمع: قسّم الشكل إلى قطع معروفة الصيغة (مستطيلات ومثلثات وأشباه منحرف وأنصاف دوائر…) واجمع مساحاتها. الطرح: أكمل شكلًا أكبر واحذف الزائد؛ مثلًا مساحة لوح فيه ثقب = مساحة اللوح − مساحة الثقب. انتبه للقياسات: بعضها يُستنتج من الأضلاع الأخرى، والنتيجة بوحدات مربعة دائمًا."),problem:e("L forma: 10 × 6 cm-ko laukizuzen bati 4 × 3 cm-ko laukizuzen bat kendu zaio izkina batean. Zein da azalera?","Una L: a un rectángulo de 10 × 6 cm se le ha quitado un rectángulo de 4 × 3 cm en una esquina. ¿Cuál es el área?","شكل L: أُزيل من مستطيل 10 × 6 سم مستطيل 4 × 3 سم في ركن. ما المساحة؟"),stepsKind:"steps",steps:[{text:e("Laukizuzen osoa.","El rectángulo entero.","المستطيل كاملًا."),math:o("$10\\cdot 6=60$")},{text:e("Kendutako zatia.","El trozo quitado.","القطعة المزالة."),math:o("$4\\cdot 3=12$")},{text:e("Kendu: 48 cm².","Resta: 48 cm².","اطرح: 48 سم²."),math:o("$60-12=48$")}],example:o("$A=A_{1}+A_{2}\\qquad A=A_{1}-A_{2}$"),takeaway:e("Zatitu eta batu, edo osatu eta kendu.","Divide y suma, o completa y resta.","قسّم واجمع، أو أكمل واطرح."),figure:i=>t.jsx(G,{language:i})},{id:"sector-ring",stage:"areas",title:e("Arkua, sektorea eta koroa","Arco, sector y corona","القوس والقطاع والحلقة"),goal:e("Arku baten luzera eta sektore eta koroa zirkular baten azalera kalkulatzea.","Calcular la longitud de un arco y el área de un sector y de una corona circular.","حساب طول قوس ومساحة قطاع وحلقة دائرية."),explanation:e("Sektore bat zirkuluaren zati bat da, eta haren angelu zentrala $360^{\\circ}$-ren zati bera. Beraz, arkua zirkunferentziaren zati hori da, $L=\\frac{2\\pi r\\cdot\\alpha}{360}$, eta sektorearen azalera zirkuluaren zati hori, $A=\\frac{\\pi r^{2}\\cdot\\alpha}{360}$: $90^{\\circ}$-ko sektorea zirkuluaren laurdena da. Koroa zirkularraren azalera zirkulu handiaren azalera ken txikiarena da: $A=\\pi\\cdot(R^{2}-r^{2})$. Kontuz: lehenik karratuak, gero kendu; ez kendu erradioak karratu aurretik. Hemen $\\pi\\approx 3{,}14$ erabiltzen dugu.","Un sector es una parte del círculo, la misma parte de $360^{\\circ}$ que su ángulo central. Así que el arco es esa parte de la circunferencia, $L=\\frac{2\\pi r\\cdot\\alpha}{360}$, y el área del sector esa parte del círculo, $A=\\frac{\\pi r^{2}\\cdot\\alpha}{360}$: un sector de $90^{\\circ}$ es un cuarto del círculo. El área de la corona circular es el área del círculo grande menos la del pequeño: $A=\\pi\\cdot(R^{2}-r^{2})$. Cuidado: primero los cuadrados, luego la resta; no restes los radios antes de elevar al cuadrado. Aquí usamos $\\pi\\approx 3{,}14$.","القطاع جزء من القرص، وهو الجزء نفسه من $360^{\\circ}$ الذي تمثله زاويته المركزية. فالقوس هو ذلك الجزء من محيط الدائرة، $L=\\frac{2\\pi r\\cdot\\alpha}{360}$، ومساحة القطاع ذلك الجزء من القرص، $A=\\frac{\\pi r^{2}\\cdot\\alpha}{360}$: قطاع $90^{\\circ}$ ربع القرص. ومساحة الحلقة الدائرية مساحة القرص الكبير ناقص مساحة الصغير: $A=\\pi\\cdot(R^{2}-r^{2})$. انتبه: المربعات أولًا ثم الطرح؛ لا تطرح نصفي القطرين قبل التربيع. نستعمل هنا $\\pi\\approx 3{,}14$."),problem:e("Kalkulatu 10 cm-ko erradioa eta $90^{\\circ}$-ko angelua dituen sektorearen azalera.","Calcula el área de un sector de 10 cm de radio y $90^{\\circ}$.","احسب مساحة قطاع نصف قطره 10 سم وزاويته $90^{\\circ}$."),stepsKind:"steps",steps:[{text:e("Zirkulu osoa.","El círculo entero.","القرص كاملًا."),math:o("$3{,}14\\cdot 10^{2}=314$")},{text:e("$90^{\\circ}$ laurdena da.","$90^{\\circ}$ es un cuarto.","$90^{\\circ}$ ربع."),math:o("$\\frac{314\\cdot 90}{360}=78{,}5$")}],example:o("$3{,}14\\cdot(5^{2}-3^{2})=50{,}24$"),takeaway:e("Sektorea eta arkua: zati $\\frac{\\alpha}{360}$. Koroa: $\\pi\\cdot(R^{2}-r^{2})$.","Sector y arco: la parte $\\frac{\\alpha}{360}$. Corona: $\\pi\\cdot(R^{2}-r^{2})$.","القطاع والقوس: الجزء $\\frac{\\alpha}{360}$. الحلقة: $\\pi\\cdot(R^{2}-r^{2})$."),figure:i=>t.jsx(H,{language:i})},{id:"area-problems",stage:"areas",title:e("Azalera- eta perimetro-problemak","Problemas de áreas y perímetros","مسائل المساحات والمحيطات"),goal:e("Eguneroko problemak ebaztea: azalera edo perimetroa behar den erabakiz.","Resolver problemas cotidianos decidiendo si hace falta el área o el perímetro.","حلّ مسائل يومية بتحديد ما إذا كانت تحتاج إلى المساحة أم المحيط."),explanation:e("Problema baten aurrean, galdetu: inguratu behar da ala estali? Hesia, zinta edo zokalo bat jartzeko, perimetroa (cm, m). Lorategia ereiteko, zorua lauzatzeko edo horma margotzeko, azalera (cm², m²). Lauza kopurua aurkitzeko, zatitu zoruaren azalera lauza baten azaleraz (unitate berean!). Bide edo marko batek irudi bat inguratzen badu, haren azalera kanpoko irudia ken barrukoa da. Prezioak: azalera bider m² bakoitzaren prezioa.","Ante un problema, pregúntate: ¿hay que rodear o cubrir? Para poner una valla, una cinta o un rodapié, el perímetro (cm, m). Para sembrar un jardín, embaldosar un suelo o pintar una pared, el área (cm², m²). Para saber cuántas baldosas, divide el área del suelo entre el área de una baldosa (¡en la misma unidad!). Si un camino o un marco rodea una figura, su área es la figura exterior menos la interior. Precios: el área por el precio de cada m².","أمام أي مسألة اسأل: هل نحيط أم نغطي؟ لوضع سياج أو شريط أو إطار سفلي نحتاج المحيط (سم، م). ولزرع حديقة أو تبليط أرضية أو طلاء جدار نحتاج المساحة (سم²، م²). ولمعرفة عدد البلاطات اقسم مساحة الأرضية على مساحة البلاطة (بالوحدة نفسها!). وإذا أحاط ممر أو إطار بشكل فمساحته هي الشكل الخارجي ناقص الداخلي. الأسعار: المساحة في سعر المتر المربع."),problem:e("5 m × 4 m-ko gela bat 50 cm-ko aldeko lauza karratuekin lauzatu nahi da. Zenbat lauza behar dira?","Se quiere embaldosar una habitación de 5 m × 4 m con baldosas cuadradas de 50 cm de lado. ¿Cuántas baldosas hacen falta?","نريد تبليط غرفة 5 م × 4 م ببلاطات مربعة طول ضلعها 50 سم. كم بلاطة نحتاج؟"),stepsKind:"steps",steps:[{text:e("Gelaren azalera.","El área de la habitación.","مساحة الغرفة."),math:o("$5\\cdot 4=20\\ \\text{m}^{2}$")},{text:e("Lauza baten azalera, m²-tan.","El área de una baldosa, en m².","مساحة البلاطة بالمتر المربع."),math:o("$0{,}5\\cdot 0{,}5=0{,}25\\ \\text{m}^{2}$")},{text:e("Zatitu.","Divide.","اقسم."),math:o("$20\\mathbin{:}0{,}25=80$")}],example:e("Hesia → perimetroa · Lauzak → azalera","Valla → perímetro · Baldosas → área","سياج ← محيط · بلاط ← مساحة"),takeaway:e("Inguratu: perimetroa. Estali: azalera. Unitate berean!","Rodear: perímetro. Cubrir: área. ¡En la misma unidad!","الإحاطة: المحيط. التغطية: المساحة. بالوحدة نفسها!"),figure:i=>t.jsx(N,{language:i})}],fa={polygon:aa,tiling:X,triangle:J,centers:V,quad:Y,circles:W,sector:Q,composite:M};function xa(i){return t.jsx(q,{...i,tools:l,stages:b,components:fa,title:{eu:"Mugitu, eraiki eta neurtu",es:"Mueve, construye y mide",ar:"حرّك وأنشئ وقِس"}})}const ha={storagePrefix:"matella-figurak-dbh1",coursePath:"/matematika/dbh1",courseTitle:{eu:"1. DBH",es:"1.º ESO",ar:"الصف الأول"},title:{eu:"Irudi lauak",es:"Figuras planas",ar:"الأشكال المستوية"},documentTitle:{eu:"Irudi lauak · 1. DBH",es:"Figuras planas · 1.º ESO",ar:"الأشكال المستوية · الصف الأول"},tagline:{eu:"Diagonalak, lauzak, triangeluen zentroak, simetriak, zirkunferentziak eta irudi konposatuak: irudi lauak sakonago.",es:"Diagonales, baldosas, centros del triángulo, simetrías, circunferencias y figuras compuestas: las figuras planas a fondo.",ar:"الأقطار والبلاط ومراكز المثلث والتناظر والدوائر والأشكال المركّبة: الأشكال المستوية بعمق."},heroArt:t.jsx(ia,{}),pathSubtitle:{eu:"Bost etapa, diagonaletatik azalera konposatuetara",es:"Cinco etapas, de las diagonales a las áreas compuestas",ar:"خمس مراحل، من الأقطار إلى المساحات المركّبة"},stages:b,topics:za,diagnostic:oa,guidedPractice:ta,exerciseBank:ua,challenges:ca,lab:{description:{eu:`${l.length} tresna irudi lauak ukitzeko: poligonoak, lauzak, triangeluak eta haien zentroak, laukiak, zirkunferentziak, sektoreak eta L formako irudiak, erronkekin.`,es:`${l.length} herramientas para tocar las figuras planas: polígonos, baldosas, triángulos y sus centros, cuadriláteros, circunferencias, sectores y figuras en L, con retos.`,ar:`${l.length} أدوات للمس الأشكال المستوية: المضلعات والبلاط والمثلثات ومراكزها والرباعيات والدوائر والقطاعات والأشكال L، مع تحديات.`},progressIds:ra,toolForTopic:ea,render:i=>t.jsx(xa,{...i})},games:{description:{eu:"Bi joko abiadura eta zehaztasuna entrenatzeko: lasterketa eta memoria.",es:"Dos juegos para entrenar rapidez y precisión: carrera y memoria.",ar:"لعبتان لتدريب السرعة والدقة: السباق والذاكرة."},progressIds:da,recordsKey:p,render:i=>t.jsx(ba,{...i})},answers:{note:{eu:"Idatzi zenbaki bat, komarekin edo puntuarekin (18,84 edo 18.84). Angeluetan, gradu-kopurua bakarrik (° gabe ere bai). Erabili π ≈ 3,14.",es:"Escribe un número, con coma o con punto (18,84 o 18.84). En los ángulos, solo los grados (también sin °). Usa π ≈ 3,14.",ar:"اكتب عددًا بالنقطة أو بالفاصلة (18.84). وفي الزوايا اكتب عدد الدرجات فقط (ويمكن دون °). استعمل π ≈ 3.14."},defaultForm:"any",inputMode:"decimal",normalizeInput:E,placeholder:()=>({eu:"Adib.: 135",es:"Ej.: 135",ar:"مثال: 135"}),wrongForm:()=>({eu:"Balioa zuzena da, baina idatzi zenbaki gisa.",es:"El valor es correcto, pero escríbelo como número.",ar:"القيمة صحيحة، لكن اكتبها عددًا."}),unreadable:{eu:"Ez dut erantzun hori ulertzen. Idatzi zenbaki bat, adibidez 135 edo 18,84.",es:"No entiendo esa respuesta. Escribe un número, por ejemplo 135 o 18,84.",ar:"لم أفهم هذه الإجابة. اكتب عددًا، مثل 135 أو 18.84."}},errorByStage:{polygons:{eu:"Diagonalak: n · (n − 3) : 2. Angeluen batura: (n − 2) · 180°. Erregularra: batura : n.",es:"Diagonales: n · (n − 3) : 2. Suma de ángulos: (n − 2) · 180°. Regular: suma : n.",ar:"الأقطار: n · (n − 3) : 2. مجموع الزوايا: (n − 2) · 180°. المنتظم: المجموع : n."},triangles:{eu:"Alde handiena < beste bien batura. Isoszelea: oinarriko angeluak berdinak.",es:"Lado mayor < suma de los otros dos. Isósceles: ángulos de la base iguales.",ar:"الضلع الأكبر < مجموع الآخرين. متساوي الساقين: زاويتا القاعدة متساويتان."},quadrilaterals:{eu:"Laukia: 360°. Paralelogramoa: aurkakoak berdinak, ondokoek 180°.",es:"Cuadrilátero: 360°. Paralelogramo: opuestos iguales, consecutivos 180°.",ar:"الرباعي: 360°. متوازي الأضلاع: المتقابلة متساوية والمتتالية 180°."},circles:{eu:"Konparatu d honekin: r, r₁ + r₂ eta r₁ − r₂. Inskribatua = zentrala : 2.",es:"Compara d con r, r₁ + r₂ y r₁ − r₂. Inscrito = central : 2.",ar:"قارن d بـ r وr₁ + r₂ وr₁ − r₂. المحيطية = المركزية : 2."},areas:{eu:"Zatitu eta batu, edo osatu eta kendu. Sektorea: zirkulua · α : 360.",es:"Divide y suma, o completa y resta. Sector: círculo · α : 360.",ar:"قسّم واجمع، أو أكمل واطرح. القطاع: القرص · α : 360."}}};function wa(){return t.jsx(C,{unit:ha})}export{wa as FigurakIntroPage};
